(window.JCPA_DATA=window.JCPA_DATA||{})["aml"]={"id":"aml","name":"قانون مكافحة غسل الأموال","full":"قانون مكافحة غسل الأموال وتمويل الإرهاب رقم (20) لسنة 2021","icon":"🕵️","articles":[{"n":"1","chapter":"","source":"يسمى هذا القانون (قانون مكافحة غسل الأموال وتمويل الإرهاب لسنة 2021) ويعمل به من تاريخ نشره في الجريدة الرسمية.","notes":[],"title":"بدء العمل بالقانون","memo":"⭐ يسمى قانون مكافحة غسل الأموال وتمويل الإرهاب لسنة 2021\n⭐ يعمل به من تاريخ نشره في الجريدة الرسمية","qs":[{"q":"يبدأ العمل بقانون مكافحة غسل الأموال وتمويل الإرهاب لسنة 2021:","o":["من تاريخ نشره في الجريدة الرسمية","بعد ثلاثين يوماً من تاريخ نشره في الجريدة الرسمية","من تاريخ إقراره من مجلس الأمة","من بداية السنة المالية التالية لنشره"],"a":0}]},{"n":"2","chapter":"","source":"أ. يكون للكلمات والعبارات التالية حيثما وردت في هذا القانون المعاني المخصصة لها ادناه ما لم تدل القرينة على غير ذلك:-\nاللجنة : اللجنة الوطنية لمكافحة غسل الأموال وتمويل الإرهاب المشكلة وفقا لأحكام هذا القانون.\nالمحافظ : محافظ البنك المركزي الأردني.\nالوحدة : وحدة مكافحة غسل الأموال وتمويل الارهاب المنشأة بمقتضى أحكام هذا القانون.\nالمال : كل عين أو حق له قيمة مادية أو معنوية في التعامل ويشمل الأصول أو الممتلكات أياً كان نوعها سواء كانت ملموسة أو غير ملموسة، منقولة أو غير منقولة وبغض النظر عن الوسيلة التي تم الحصول عليها بها والوثائق أو المستندات القانونية بما فيها الالكترونية أو الرقمية التي تثبت حق ملكية تلك الأصول أو حصة أو مصلحة فيها سواء كانت داخل المملكة أو خارجها بما في ذلك العملات بالدينار الأردني أو العملات الأجنبية والحسابات المصرفية وصناديق الودائع والاوراق المالية والاوراق التجارية والشيكات السياحية والحوالات وخطابات الضمان والاعتمادات المستندية والأصول الالكترونية او الرقمية أو الافتراضية وأي فوائد أو أرباح أو دخول أخرى مترتبة على أو متولدة من هذه الأموال أو الأصول والموارد الاقتصادية بما فيها النفط والموارد الطبيعية.\nالمتحصلات : أي أموال أو أصول ناشئــة أو تم الحصول عليها، بصورة مباشرة أو غير مباشرة، من خلال ارتكاب فعل أو الامتناع عن القيام بفعل بما يشكل جريمة وفق التشريعات النافذة في المملكة .\nالجريمة الأصلية : أي جناية او جنحة معاقب عليها وفقا للتشريعات النافذة.\nالجهة النظيرة : الجهة التي تمنح بموجب التشريعات السارية في اي دولة الاختصاصات اللازمة لمكافحة عمليات غسل الاموال وتمويل الارهاب وتخضع لقواعد قانونية كافية للالتزام بسرية المعلومات.\nالجهات المبلغة : المؤسسات المالية والمهن والأعمال غير المالية.\nالمجموعة المالية : مجموعة تتكون من شركة أم أو أي نوع آخر من الاشخاص المعنوية تملك حصص السيطرة على باقي الأشخاص الاعتباريين في المجموعة وتقوم بتنسيق الوظائف معها لإحكام الرقابة عليها مع وجود فروع أو شركات تابعة.\nالأدوات القابلة للتداول لحاملها : أي أداة نقدية على شكل وثيقة لحاملها ينتقل حق الانتفاع بها بمجرد التسليم بما في ذلك تلك الموقعة والمحذوف منها اسم المستفيد.\nالمستفيد الحقيقي : الشخص الطبيعي الذي يمتلك أو يمارس سيطرة فعلية نهائية على العميل بصورة مباشرة أو غير مباشرة أو الذي تتم العمليات نيابة عنه أو يمارس سيطرة فعلية نهائية على شخص اعتباري أو ترتيب قانوني .\nالعميل : من يقوم أو يشرع بالقيام بأي من الأعمال مع احدى المؤسسات المالية أو المهن والأعمال غير المالية.\nالتجميد : حظر نقل الأموال أو تحويلها أو التصرف فيها من أشخاص أو جماعات أو كيانات ادرجت وفقا لأحكام هذا القانون.\nالحجز : حظر نقل الأموال والمعدات والوسائط أو تحويلها أو التصرف فيها لمدة محددة بموجب اجراء صادر عن الجهة المختصة بذلك.\nالجهات الرقابية والإشرافية : السلطات المختصة المسؤولة عن ضمان التزام الجهات المبلغة بمتطلبات مكافحة غسل الأموال وتمويل الإرهاب بما فيها البنك المركزي الأردني وهيئة الأوراق المالية ووزارة الصناعة والتجارة والتموين وهيئة تنظيم قطاع الاتصالات ودائرة مراقبة الشركات ودائرة الأراضي والمساحة ووزارة الداخلية وأي جهة أخرى تقرر اللجنة اعتبارها جهة رقابية وإشرافية بموافقة مجلس الوزراء.\nالجهات المختصة : الجهات القضائية والإدارية والأمنية والرقابية والاشرافية المسؤولة عن مكافحة غسل الأموال أو تمويل الإرهاب وأي جهة أخرى تقرر اللجنة اعتبارها جهة مختصة بموافقة مجلس الوزراء.\nإجراءات العناية الواجبة : عملية التعرف او التحقق من معلومات العميل او المستفيد الحقيقي وطبيعة عمله والغرض من علاقة العمل بشكل يمكن الجهات المبلغة من تقييم مدى تعرضها للمخاطر.\nالأشخاص السياسيون المعرضون للمخاطر : الأشخاص الذين يتولون مهام عليا في المملكة أو خارجها بما في ذلك السياسيون والمسؤولون الحكوميون والقضائيون والعسكريون، وكبار الموظفين التنفيذيين في الشركات المملوكة للحكومة، ومسؤولو الأحزاب السياسية أو الذين يتولون مهام بارزة في منظمة دولية بمن فيهم أعضاء الإدارة العليا كالمديرين ونواب المديرين وأعضاء المجالس أو المناصب التي في حكمها وأفراد عائلات أي منهم والأشخاص المقربين منهم .\nب. لمقاصد هذا القانون تعتمد التعريفات الواردة في أي قانون آخر ذي علاقة حسب مقتضى الحال شريطة ان لا تتعارض هذه التعريفات مع أحكام هذا القانون.","notes":[],"title":"التعريفات","memo":"⭐ المحافظ: محافظ البنك المركزي الأردني\n⭐ الجريمة الأصلية: أي جناية أو جنحة معاقب عليها وفقاً للتشريعات النافذة\n⭐ الجهات المبلغة: المؤسسات المالية والمهن والأعمال غير المالية\n⭐ المستفيد الحقيقي: الشخص الطبيعي صاحب السيطرة الفعلية النهائية؛ وتضاف الجهات الرقابية/المختصة بقرار اللجنة وموافقة مجلس الوزراء","qs":[{"q":"تعرف «الجريمة الأصلية» وفق قانون مكافحة غسل الأموال وتمويل الإرهاب بأنها:","o":["أي جناية أو جنحة معاقب عليها وفقاً للتشريعات النافذة","أي جناية معاقب عليها فقط دون الجنح","أي جريمة يزيد الحد الأدنى لعقوبتها على سنة","أي جريمة منصوص عليها في قانون العقوبات حصراً"],"a":0},{"q":"«المستفيد الحقيقي» وفق التعريفات الواردة في القانون هو:","o":["الشخص الطبيعي الذي يمتلك أو يمارس سيطرة فعلية نهائية على العميل","أي شخص طبيعي أو اعتباري يملك حصة في رأسمال العميل","الشخص الاعتباري المسيطر على العميل","الشخص الذي يفتح الحساب باسمه لدى الجهة المبلغة"],"a":0},{"q":"أي مما يلي لا يعد من الجهات الرقابية والإشرافية المذكورة صراحة في تعريفها؟","o":["دائرة ضريبة الدخل والمبيعات","هيئة الأوراق المالية","دائرة مراقبة الشركات","هيئة تنظيم قطاع الاتصالات"],"a":0},{"q":"يتم اعتبار جهة أخرى «جهة رقابية وإشرافية» لغايات القانون بقرار من:","o":["اللجنة بموافقة مجلس الوزراء","مجلس الوزراء بناء على تنسيب المحافظ","رئيس الوحدة بموافقة اللجنة","المحافظ بموافقة مجلس إدارة البنك المركزي"],"a":0}]},{"n":"3","chapter":"","source":"أ. يعد مرتكباً لجريمة غسل الاموال:-\n1. كل شخص يعلم بأن الأموال متحصلات جريمة اصلية وسواء ارتكب الجريمة الاصلية ام لا وذلك في حال قيامه عمداً بارتكاب أي من الأفعال التالية:-\nأ. تحويل الأموال أو نقلها لغايات تمويه أو إخفاء مصدرها غير المشروع أو لغايات مساعدة أي شخص متورط في ارتكاب الجريمة الأصلية أو ساهم في ارتكابها.\nب. إخفاء أو تمويه الطبيعة الحقيقية للأموال أو مصدرها أو مكانها أو طريقة التصرف بها أو حركتها أو ملكيتها أو أي من الحقوق المرتبطة بهذه الأموال.\nج. اكتساب الأموال أو استخدامها أو إدارتها أو استثمارها أو حيازتها.\n2. كل شخص يشرع في ارتكاب أي من الأفعال المشار إليها في البند (1) من هذه الفقرة أو يساعد أو يحرض أو يسهل أو يخفي ارتكاب هذه الجريمة أو يتدخل في ارتكابها أو يعمل كشريك أو يرتبط مع أو يتآمر لمحاولة ارتكاب هذه الجريمة.\nب. عند اثبات ان الاموال هي متحصلات جريمة فلا يشترط أن يكون قد تم إدانة شخص بارتكاب الجريمة الاصلية.\nج. لغايات هذا القانون، تشمل متحصلات الجريمة ما يلي:-\n1. أي متحصلات ناجمة عن ارتكاب فعل اجرامي خارج المملكة شريطة أن يشكل هذا الفعل جريمة في المملكة وفي الدولة التي وقع فيها.\n2. أي متحصلات ناجمة عن أي فعل يعتبر جريمة بمقتضى اتفاقيات دولية صادقت عليها المملكة شريطة ان يكون معاقبا عليها في القانون الاردني.","notes":[],"title":"جريمة غسل الأموال","memo":"⭐ يشترط العلم بأن الأموال متحصلات جريمة أصلية سواء ارتكب الجريمة الأصلية أم لا، مع القيام عمداً بالتحويل أو الإخفاء أو الاكتساب/الاستخدام/الحيازة\n⭐ الشروع والمساعدة والتحريض والتسهيل والتدخل والاشتراك والتآمر تعد ارتكاباً للجريمة\n⭐ لا يشترط إدانة شخص بالجريمة الأصلية عند إثبات أن الأموال متحصلات جريمة\n⭐ متحصلات الفعل خارج المملكة تشمل بشرط أن يشكل جريمة في المملكة وفي الدولة التي وقع فيها","qs":[{"q":"عند إثبات أن الأموال هي متحصلات جريمة، فإنه لغايات جريمة غسل الأموال:","o":["لا يشترط أن يكون قد تم إدانة شخص بارتكاب الجريمة الأصلية","يشترط صدور حكم قطعي بالإدانة في الجريمة الأصلية","يشترط أن يكون مرتكب الغسل هو نفسه مرتكب الجريمة الأصلية","يشترط تقديم شكوى من المتضرر من الجريمة الأصلية"],"a":0},{"q":"تشمل متحصلات الجريمة المتحصلات الناجمة عن فعل إجرامي ارتكب خارج المملكة بشرط أن:","o":["يشكل الفعل جريمة في المملكة وفي الدولة التي وقع فيها","يشكل الفعل جريمة في الدولة التي وقع فيها فقط","يكون مرتكب الفعل أردني الجنسية","تكون الأموال قد أدخلت إلى المملكة"],"a":0},{"q":"حالة عملية: اشترى شخص عقاراً بأموال يعلم أنها ناتجة عن جريمة احتيال ارتكبها غيره. وفق القانون فإنه:","o":["يعد مرتكباً لجريمة غسل الأموال لأن اكتساب الأموال أو استخدامها مع العلم بمصدرها من أفعال الغسل","لا يعد مرتكباً لجريمة لأنه لم يرتكب الجريمة الأصلية","لا يعد مرتكباً لجريمة إلا إذا قام بتحويل الأموال إلى خارج المملكة","يعد شريكاً في جريمة الاحتيال فقط دون جريمة الغسل"],"a":0}]},{"n":"4","chapter":"","source":"أ. يعد مرتكباً لجريمة تمويل الإرهاب كل شخص:-\n1. يقوم بأي وسيلة كانت بطريقة مباشرة أو غير مباشرة بإرادته بتقديم أو جمع الاموال سواءً من مصدر مشروع أو غير مشروع مع علمه بأن تلك الاموال ستستخدم كلياً أو جزئيا في ارتكاب عمل إرهابي أومن قبل شخص إرهابي أو منظمة إرهابية.\n2. يساهم عمداً في ارتكاب جريمة تمويل الإرهاب مع مجموعة من الأشخاص أو يدعمهم لارتكابها.\n3. يقوم بتمويل سفر الأشخاص إلى دول غير دولة إقامتهم أو جنسيتهم لغايات قيامهم بارتكاب أو التخطيط أو التحضير أو المشاركة في ارتكاب أو تسهيل ارتكاب الأعمال الإرهابية أو توفير أو تلقي التدريب عليها.\n4. يساهم في ارتكاب أي من جرائم تمويل الإرهاب المشار اليها في هذه الفقرة أو يقوم بتنظيم أو توجيه أشخاص آخرين لارتكابها.\n5. يشرع في ارتكاب أي من الجرائم المنصوص عليها في هذه الفقرة .\nب. تقع جريمة تمويل الإرهاب المنصوص عليها في الفقرة (أ) من هذه المادة، حتى لو لم يقع العمل الارهابي أو لم يتم الشروع في ارتكابه وسواء استخدمت هذه الأموال لارتكاب عمل إرهابي أو محاولة ارتكابه أو لم تستخدم وسواء ارتبطت بعمل إرهابي معين أم لم ترتبط وبغض النظر عن مكان وقوع العمل الإرهابي أو المكان الذي كان من المفترض أن يقع فيه.","notes":[],"title":"جريمة تمويل الإرهاب","memo":"⭐ تقديم أو جمع الأموال سواء من مصدر مشروع أو غير مشروع مع العلم باستخدامها كلياً أو جزئياً في عمل إرهابي أو من قبل إرهابي أو منظمة إرهابية\n⭐ يشمل تمويل سفر الأشخاص إلى دول غير دولة إقامتهم أو جنسيتهم لغايات إرهابية، والشروع\n⭐ تقع الجريمة حتى لو لم يقع العمل الإرهابي أو لم تستخدم الأموال، وبغض النظر عن مكان وقوعه","qs":[{"q":"لغايات جريمة تمويل الإرهاب، فإن مصدر الأموال المقدمة أو المجموعة:","o":["لا عبرة به، سواء كان مشروعاً أو غير مشروع","يجب أن يكون غير مشروع","يجب أن يكون متحصلات جريمة أصلية","يجب أن يكون من خارج المملكة"],"a":0},{"q":"حالة عملية: جمع شخص أموالاً مع علمه بأنها ستستخدم من قبل منظمة إرهابية، إلا أن العمل الإرهابي لم يقع ولم تستخدم الأموال. وفق القانون:","o":["تقع جريمة تمويل الإرهاب رغم عدم وقوع العمل الإرهابي وعدم استخدام الأموال","لا تقع الجريمة لعدم وقوع العمل الإرهابي","يعد الفعل شروعاً فقط لا يعاقب عليه","لا تقع الجريمة إلا إذا ارتبطت الأموال بعمل إرهابي معين"],"a":0},{"q":"يعد مرتكباً لجريمة تمويل الإرهاب من يمول سفر الأشخاص:","o":["إلى دول غير دولة إقامتهم أو جنسيتهم لغايات ارتكاب الأعمال الإرهابية أو التدريب عليها","إلى أي دولة لغايات العمل أو الدراسة","إلى دولة جنسيتهم لغايات الإقامة الدائمة","إلى خارج المملكة دون الحصول على تصريح من الوحدة"],"a":0}]},{"n":"5","chapter":"","source":"تشكل لجنة تسمى (اللجنة الوطنية لمكافحة غسل الاموال وتمويل الإرهاب) برئاسة المحافظ وعضوية كل من:-\nأ. نائب المحافظ الذي يسميه المحافظ نائبا لرئيس اللجنة.\nب. امين عام وزارة العدل .\nج. امين عام وزارة الداخلية .\nد. أمين عام وزارة الخارجية وشؤون المغتربين.\nهـ. مدير عام دائرة الجمارك .\nو. مدير عام دائرة ضريبة الدخل والمبيعات .\nز. مدير عام دائرة الاراضي والمساحة .\nح. مراقب عام الشركات.\nط. أمين عام سجل الجمعيات.\nي. مفوض من مجلس مفوضي هيئة الاوراق المالية يسميه رئيس مجلس المفوضين.\nك. ممثل عن دائرة المخابرات العامة .\nل. رئيس الوحدة .\nم. ممثل عن أي جهة اخرى يتم اضافتها بقرار من مجلس الوزراء بناء على تنسيب رئيس اللجنة.","notes":[],"title":"تشكيل اللجنة الوطنية","memo":"⭐ برئاسة المحافظ (محافظ البنك المركزي)، ونائب الرئيس نائب المحافظ الذي يسميه المحافظ\n⭐ تضم أمناء عامين لوزارات العدل والداخلية والخارجية، ومديري الجمارك وضريبة الدخل والمبيعات والأراضي والمساحة، ومراقب عام الشركات، وأمين عام سجل الجمعيات، ومفوضاً من هيئة الأوراق المالية، وممثل المخابرات العامة، ورئيس الوحدة\n⭐ إضافة ممثل أي جهة أخرى بقرار من مجلس الوزراء بناء على تنسيب رئيس اللجنة","qs":[{"q":"يرأس اللجنة الوطنية لمكافحة غسل الأموال وتمويل الإرهاب:","o":["محافظ البنك المركزي الأردني","وزير العدل","رئيس الوحدة","وزير المالية"],"a":0},{"q":"أي مما يلي ليس من أعضاء اللجنة الوطنية لمكافحة غسل الأموال وتمويل الإرهاب؟","o":["أمين عام وزارة المالية","مدير عام دائرة ضريبة الدخل والمبيعات","مراقب عام الشركات","أمين عام سجل الجمعيات"],"a":0},{"q":"تتم إضافة ممثل عن أي جهة أخرى إلى عضوية اللجنة الوطنية بقرار من:","o":["مجلس الوزراء بناء على تنسيب رئيس اللجنة","رئيس اللجنة بناء على تنسيب رئيس الوحدة","اللجنة بأغلبية أعضائها","رئيس الوزراء بناء على تنسيب وزير العدل"],"a":0}]},{"n":"6","chapter":"","source":"أ. تتولى اللجنة أي مهام وصلاحيات متعلقة بمكافحة غسل الأموال وتمويل الإرهاب وانتشار اسلحة الدمار الشامل بما في ذلك ما يلي:-\n1. رسم السياسة العامة لمكافحة غسل الأموال وتمويل الإرهاب و انتشار اسلحة الدمار الشامل وتطوير الاستراتيجيات واعتماد الخطط اللازمة لتنفيذها في ضوء مخاطر غسل الأموال وتمويل الإرهاب في المملكة ومتابعة الجهات المسؤولة عن تنفيذها.\n2. اعتماد اجراءات تقييم مخاطر غسل الأموال وتمويل الإرهاب وانتشار اسلحة الدمار الشامل في المملكة وتحديثه.\n3. تزويد الجهات المختصة بالمعلومات المتعلقة بتقييمات مخاطر غسل الأموال وتمويل الإرهاب وانتشار اسلحة الدمار الشامل .\n4. تزويد المؤسسات المالية والمهن والأعمال غير المالية بالمعلومات المتعلقة بنتائج عمليات تقييم المخاطر.\n5. تعزيز التعاون والتنسيق في مجال تطبيق الأطر اللازمة لمكافحة غسل الأموال وتمويل الإرهاب وانتشار أسلحة الدمار الشامل في المملكة.\n6. المشاركة في المحافل الدولية ذات العلاقة بالسياسة العامة لمكافحة غسل الأموال وتمويل الإرهاب و انتشار أسلحة الدمار الشامل.\n7. اقتراح مشروعات التشريعات المتعلقة بغسل الأموال وتمويل الارهاب وانتشار أسلحة الدمار الشامل .\n8. متابعة المستجدات العالمية في مجال مكافحة غسل الأموال وتمويل الإرهاب وانتشار أسلحة الدمار الشامل واقتراح الاجراءات اللازمة بشأنها.\n9. تقييم فاعلية نظم مكافحة غسل الأموال وتمويل الإرهاب وانتشار اسلحة الدمار الشامل وتنسيق جمع الاحصائيات والمعلومات والبيانات الوطنية من جميع الجهات ذات العلاقة وبيان الإجراءات الواجب اتخاذها لمعالجة أوجه القصور فيها.\n10. تحديد شروط اشغال وظيفة رئيس الوحدة واسباب انتهاء خدماته.\n11. الموافقة على الموازنة السنوية المقترحة للوحدة وإقرار بياناتها المالية الختامية.\n12. تعيين محاسب قانوني للوحدة وتحديد أتعابه.\nب. تلتزم الجهات الممثلة في اللجنة بتقديم تقرير عن إجراءاتها ودورها في مكافحة جرائم غسل الأموال والجرائم الأصلية المرتبطة بها وجرائم تمويل الإرهاب وانتشار اسلحة الدمار الشامل.\nج. تحدد آلية عمل اللجنة والنصاب القانوني لاجتماعاتها واتخاذ قراراتها وتشكيل أمانة سرها وسائر الأحكام المتعلقة بها بموجب نظام يصدر لهذه الغاية .","notes":[],"title":"مهام اللجنة الوطنية","memo":"⭐ رسم السياسة العامة واعتماد إجراءات تقييم المخاطر الوطنية واقتراح مشروعات التشريعات\n⭐ تحديد شروط إشغال وظيفة رئيس الوحدة وأسباب انتهاء خدماته\n⭐ الموافقة على الموازنة السنوية للوحدة وإقرار بياناتها الختامية وتعيين محاسب قانوني للوحدة وتحديد أتعابه\n⭐ آلية عمل اللجنة ونصابها وأمانة سرها تحدد بنظام","qs":[{"q":"الجهة المختصة بتعيين محاسب قانوني لوحدة مكافحة غسل الأموال وتمويل الإرهاب وتحديد أتعابه هي:","o":["اللجنة الوطنية لمكافحة غسل الأموال وتمويل الإرهاب","رئيس الوحدة","ديوان المحاسبة","مجلس إدارة البنك المركزي"],"a":0},{"q":"تتم الموافقة على الموازنة السنوية المقترحة للوحدة وإقرار بياناتها المالية الختامية من قبل:","o":["اللجنة الوطنية","مجلس الوزراء","المحافظ منفرداً","مجلس الأمة"],"a":0},{"q":"أي مما يلي لا يعد من مهام اللجنة الوطنية الواردة في القانون؟","o":["تلقي الإخطارات عن العمليات المشبوهة وتحليلها","اقتراح مشروعات التشريعات المتعلقة بغسل الأموال وتمويل الإرهاب","تحديد شروط إشغال وظيفة رئيس الوحدة وأسباب انتهاء خدماته","اعتماد إجراءات تقييم مخاطر غسل الأموال وتمويل الإرهاب في المملكة"],"a":0},{"q":"تحدد آلية عمل اللجنة الوطنية والنصاب القانوني لاجتماعاتها وتشكيل أمانة سرها بموجب:","o":["نظام يصدر لهذه الغاية","تعليمات يصدرها المحافظ","قرار من رئيس الوزراء","تعليمات تصدرها الوحدة"],"a":0}]},{"n":"7","chapter":"","source":"أ. تنشأ وحدة تسمى (وحدة مكافحة غسل الاموال وتمويل الارهاب) تتمتع باستقلال مالي وإداري وترتبط بالمحافظ .\nب. يعين رئيس الوحدة بقرار من اللجنة بناء على تنسيب رئيسها ويحدد راتبه وعلاواته وسائر حقوقه المالية بمقتضى قرار تعيينه .\nج. يكون للوحدة جهاز تنفيذي من الموظفين يتم تعيينهم وفقا لاحكام نظام الموظفين المعمول به في البنك المركزي الأردني ولهذه الغاية يمارس رئيس اللجنة صلاحيات مجلس إدارة البنك المركزي ويمارس رئيس الوحدة صلاحيات المحافظ المنصوص عليها في ذلك النظام.\nد. لرئيس الوحدة تفويض أي من صلاحياته المنصوص عليها في هذا القانون او الانظمة او التعليمات او القرارات الصادرة بمقتضى أي منها لأي من موظفي الوحدة على ان يكون التفويض خطياً ومحدداً.\nهـ. تنظم جميع الشؤون المتعلقة بالوحدة بمقتضى نظام يصدر لهذه الغاية .","notes":[],"title":"وحدة مكافحة غسل الأموال","memo":"⭐ تتمتع باستقلال مالي وإداري وترتبط بالمحافظ\n⭐ يعين رئيسها بقرار من اللجنة بناء على تنسيب رئيسها، وتحدد حقوقه المالية بقرار تعيينه\n⭐ موظفوها وفق نظام موظفي البنك المركزي: رئيس اللجنة يمارس صلاحيات مجلس الإدارة ورئيس الوحدة صلاحيات المحافظ\n⭐ تفويض صلاحيات رئيس الوحدة لموظفيها خطياً ومحدداً","qs":[{"q":"ترتبط وحدة مكافحة غسل الأموال وتمويل الإرهاب بـ:","o":["المحافظ","رئيس الوزراء","وزير العدل","وزير الداخلية"],"a":0},{"q":"يعين رئيس الوحدة بقرار من:","o":["اللجنة بناء على تنسيب رئيسها","مجلس الوزراء بناء على تنسيب المحافظ","المحافظ بموافقة مجلس إدارة البنك المركزي","رئيس الوزراء بناء على تنسيب اللجنة"],"a":0},{"q":"لغايات تعيين موظفي الجهاز التنفيذي للوحدة وفق نظام موظفي البنك المركزي، يمارس رئيس الوحدة صلاحيات:","o":["المحافظ","مجلس إدارة البنك المركزي","رئيس اللجنة","مجلس الوزراء"],"a":0},{"q":"يشترط في تفويض رئيس الوحدة لأي من صلاحياته لموظفي الوحدة أن يكون:","o":["خطياً ومحدداً","بموافقة اللجنة المسبقة","لمدة لا تزيد على سنة","بموافقة المحافظ"],"a":0}]},{"n":"8","chapter":"","source":"أ. يكون للوحدة موازنة مستقلة وتبدأ سنتها المالية في اليوم الاول من شهر كانون الثاني من كل سنة وتنتهي في اليوم الحادي والثلاثين من شهر كانون الاول من السنة ذاتها.\nب. تتكون الموارد المالية للوحدة مما يلي: -\n1. المخصصات التي يرصدها لها البنك المركزي الاردني.\n2. المخصصات التي ترصد لها في الموازنة العامة للدولة.\n3. المساعدات او المنح او الهبات او التبرعات التي ترد اليها شريطة موافقة مجلس الوزراء عليها اذا كانت من مصدر غير أردني .\nج. تتمتع الوحدة بالإعفاءات والتسهيلات التي تتمتع بها الوزارات والدوائر الحكومية.","notes":[],"title":"موازنة الوحدة ومواردها","memo":"⭐ موازنة مستقلة، والسنة المالية من 1 كانون الثاني إلى 31 كانون الأول\n⭐ الموارد: مخصصات البنك المركزي، ومخصصات الموازنة العامة، والمساعدات والمنح والهبات والتبرعات\n⭐ المساعدات من مصدر غير أردني تشترط موافقة مجلس الوزراء\n⭐ تتمتع بإعفاءات وتسهيلات الوزارات والدوائر الحكومية","qs":[{"q":"يشترط لقبول الوحدة المساعدات أو المنح أو الهبات أو التبرعات إذا كانت من مصدر غير أردني موافقة:","o":["مجلس الوزراء","اللجنة الوطنية","المحافظ","وزير التخطيط والتعاون الدولي"],"a":0},{"q":"تبدأ السنة المالية للوحدة في:","o":["اليوم الأول من شهر كانون الثاني وتنتهي في 31 كانون الأول من السنة ذاتها","اليوم الأول من شهر نيسان وتنتهي في 31 آذار من السنة التالية","اليوم الأول من شهر تموز وتنتهي في 30 حزيران من السنة التالية","تاريخ إقرار موازنتها من اللجنة"],"a":0},{"q":"أي مما يلي لا يعد من الموارد المالية للوحدة وفق القانون؟","o":["الغرامات المستوفاة عن مخالفات أحكام القانون","المخصصات التي يرصدها لها البنك المركزي الأردني","المخصصات التي ترصد لها في الموازنة العامة للدولة","المنح والهبات والتبرعات التي ترد إليها"],"a":0}]},{"n":"9","chapter":"","source":"تتولى الوحدة المهام والصلاحيات التالية:-\nأ. تلقي الإخطارات والتبليغات المنصوص عليها في هذا القانون و أي معلومات أخرى مرتبطة بغسل أموال او جريمة أصلية مرتبطة بها او تمويل إرهاب.\nب. تحليل الإخطارات والتبليغات والمعلومات المشار إليها في الفقرة (أ) من هذه المادة والمادتين (11) و(12) من هذا القانون .\nج. إحالة المعلومات ونتائج التحليل الذي قامت به إلى المدعي العام المختص في حال وجود شبهة بارتكاب جريمة غسل أموال أو جريمة أصلية مرتبطة بها أو تمويل إرهاب من خلال استخدام وسائل آمنة ومحمية لهذه الغاية.\nد. تحليل انماط جرائم غسل الأموال وتمويل الإرهاب وآلياتها وأساليبها وإعداد موجز عنها لنشرها .\nهـ. تلقي المعلومات والتقارير المتعلقة بالمعاملات النقدية والتحويلات الالكترونية والأموال المنقولة عبر الحدود وفقا لما تحدده الجهات المختصة.\nو. تزويد الجهات المختصة بالمعلومات او بنتائج التحليل من تلقاء نفسها أو بناء على طلب من تلك الجهات.\nز. نشر إحصائيات دورية عن عدد العمليات التي يشتبه أنها مرتبطة بغسل الأموال او الجريمة الأصلية المرتبطة بها أو تمويل الإرهاب التي تم تلقيها واحالتها وتوزيعها وتصنيفها حسب الجهات والتحقيقات وعن عدد أحكام الإدانة الصادرة والممتلكات المصادرة أو المحجوزة أو المجمدة والمساعدات القانونية المتبادلة وغيرها من طلبات التعاون الدولي التي تم تقديمها أو تلقيها.\nح. دعم البرامج والانشطة الهادفة الى تعزيز قدرات المملكة في مكافحة غسل الأموال وتمويل الارهاب وانتشار اسلحة الدمار الشامل .\nط. أي مهام أو صلاحيات أخرى منصوص عليها في هذا القانون والأنظمة والتعليمات والقرارات الصادرة بمقتضاه.","notes":[],"title":"مهام وصلاحيات الوحدة","memo":"⭐ تلقي الإخطارات والتبليغات والمعلومات وتحليلها\n⭐ إحالة المعلومات ونتائج التحليل إلى المدعي العام المختص عند وجود شبهة باستخدام وسائل آمنة ومحمية\n⭐ تزويد الجهات المختصة بالمعلومات من تلقاء نفسها أو بناء على طلبها، ونشر إحصائيات دورية","qs":[{"q":"تحيل الوحدة المعلومات ونتائج التحليل في حال وجود شبهة بارتكاب جريمة غسل أموال أو تمويل إرهاب إلى:","o":["المدعي العام المختص","المحكمة المختصة مباشرة","الجهة الرقابية والإشرافية","اللجنة الوطنية"],"a":0},{"q":"تزود الوحدة الجهات المختصة بالمعلومات أو بنتائج التحليل:","o":["من تلقاء نفسها أو بناء على طلب من تلك الجهات","بناء على طلب من تلك الجهات فقط","بعد موافقة اللجنة الوطنية فقط","بقرار من المدعي العام فقط"],"a":0},{"q":"أي مما يلي لا يعد من مهام الوحدة وفق القانون؟","o":["رسم السياسة العامة لمكافحة غسل الأموال وتمويل الإرهاب","تحليل أنماط جرائم غسل الأموال وتمويل الإرهاب وإعداد موجز عنها لنشرها","نشر إحصائيات دورية عن عدد العمليات المشتبه بها","تلقي المعلومات المتعلقة بالأموال المنقولة عبر الحدود"],"a":0}]},{"n":"10","chapter":"","source":"للوحدة ان تلزم الجهات المبلغة بأن توقف جميع الإجراءات والمعاملات الجارية على العملية التي تم الإخطار او التبليغ عنها وفقاً لأحكام هذا القانون لمدة لا تزيد على خمسة أيام عمل.","notes":[],"title":"وقف الإجراءات والمعاملات","memo":"⭐ للوحدة إلزام الجهات المبلغة بوقف جميع الإجراءات والمعاملات الجارية على العملية المخطر عنها\n⭐ مدة الوقف لا تزيد على خمسة أيام عمل","qs":[{"q":"للوحدة أن تلزم الجهات المبلغة بوقف الإجراءات والمعاملات الجارية على العملية التي تم الإخطار عنها لمدة لا تزيد على:","o":["خمسة أيام عمل","سبعة أيام عمل","عشرة أيام عمل","ثلاثة أيام عمل"],"a":0},{"q":"الجهة التي تملك صلاحية إلزام الجهات المبلغة بوقف المعاملات الجارية على العملية المخطر عنها وفق المادة (10) هي:","o":["الوحدة","المدعي العام المختص","الجهة الرقابية والإشرافية","اللجنة الوطنية"],"a":0}]},{"n":"11","chapter":"","source":"أ. للوحدة طلب المعلومات والبيانات والوثائق من الجهات المبلغة أو الجهات المختصة لغايات قيامها بمهامها أو بناء على طلب من جهة نظيرة.\nب. تلتزم الجهات المشار إليها في الفقرة (أ) من هذه المادة بتزويد الوحدة بالمعلومات والبيانات والوثائق خلال المدة المحددة في الطلب.\nج. تحدد الوحدة آلية الحصول على المعلومات والبيانات والوثائق المشار إليها في هذه المادة.","notes":[],"title":"طلب المعلومات من الجهات","memo":"⭐ للوحدة طلب المعلومات والوثائق من الجهات المبلغة أو المختصة لمهامها أو بناء على طلب جهة نظيرة\n⭐ تلتزم الجهات بالتزويد خلال المدة المحددة في الطلب\n⭐ الوحدة تحدد آلية الحصول على المعلومات","qs":[{"q":"تلتزم الجهات المبلغة بتزويد الوحدة بالمعلومات والبيانات والوثائق المطلوبة:","o":["خلال المدة المحددة في الطلب","خلال خمسة أيام عمل من تاريخ الطلب","خلال ثلاثين يوماً من تاريخ الطلب","خلال سبعة أيام من تاريخ الطلب"],"a":0},{"q":"يحق للوحدة طلب المعلومات والبيانات من الجهات المبلغة أو المختصة:","o":["لغايات قيامها بمهامها أو بناء على طلب من جهة نظيرة","بعد الحصول على إذن من المدعي العام فقط","بعد موافقة اللجنة الوطنية","بموجب قرار قضائي فقط"],"a":0}]},{"n":"12","chapter":"","source":"أ. للوحدة الحق في تبادل المعلومات مع الجهات النظيرة تلقائياً أو بناء على طلب شريطة المعاملة بالمثل وعلى ان لا تستخدم هذه المعلومات الا في الاغراض المتعلقة بمكافحة غسل الأموال والجريمة الأصلية المرتبطة بها وتمويل الإرهاب.\nب. يشترط الحصول على موافقة الجهة النظيرة التي قدمت المعلومات المشار اليها في الفقرة (أ) من هذه المادة قبل الإفصاح عنها لطرف ثالث أو عند استخدامها لغايات التحقيق والادعاء.\nج. للوحدة الحق في ابرام مذكرات تفاهم مع الجهات النظيرة لتنظيم تبادل المعلومات.","notes":[],"title":"تبادل المعلومات مع النظيرة","memo":"⭐ تبادل المعلومات مع الجهات النظيرة تلقائياً أو بناء على طلب بشرط المعاملة بالمثل\n⭐ لا تستخدم إلا لأغراض مكافحة غسل الأموال والجريمة الأصلية وتمويل الإرهاب\n⭐ يشترط موافقة الجهة النظيرة قبل الإفصاح لطرف ثالث أو الاستخدام للتحقيق والادعاء\n⭐ للوحدة إبرام مذكرات تفاهم","qs":[{"q":"يشترط لتبادل الوحدة المعلومات مع الجهات النظيرة:","o":["المعاملة بالمثل","موافقة مجلس الوزراء","وجود اتفاقية ثنائية مصادق عليها","موافقة المدعي العام المختص"],"a":0},{"q":"قبل إفصاح الوحدة عن معلومات قدمتها جهة نظيرة لطرف ثالث أو استخدامها لغايات التحقيق والادعاء يشترط الحصول على موافقة:","o":["الجهة النظيرة التي قدمت المعلومات","اللجنة الوطنية","المحافظ","وزارة العدل"],"a":0},{"q":"حالة عملية: تلقت الوحدة معلومات من جهة نظيرة أجنبية، وطلبت جهة حكومية استخدامها لأغراض تحصيل ضرائب لا علاقة لها بغسل الأموال. وفق القانون:","o":["لا يجوز ذلك لأن المعلومات لا تستخدم إلا في الأغراض المتعلقة بمكافحة غسل الأموال والجريمة الأصلية المرتبطة بها وتمويل الإرهاب","يجوز ذلك بموافقة رئيس الوحدة","يجوز ذلك بموافقة اللجنة الوطنية","يجوز ذلك إذا كانت الجهة الطالبة جهة حكومية"],"a":0}]},{"n":"13","chapter":"","source":"أ. تتخذ الوحدة الإجراءات اللازمة لضمان أمن المعلومات والوثائق التي يتم تلقيها ومعالجتها واحالتها والاحتفاظ بها بشكل آمن، على ان يتم استخدامها وفقاً لتعليمات يصدرها رئيس الوحدة لهذه الغاية.\nب. يحظر على رئيس الوحدة وموظفيها افشاء المعلومات التي يطلعون عليها أو يعلمون بها بحكم عملهم بطريقة مباشرة أو غير مباشرة ولا يجوز الافصاح عن هذه المعلومات بأي صورة كانت الا للأغراض المبينة في هذا القانون ويستمر هذا الحظر الى ما بعد انتهاء عملهم في الوحدة .\nج. يسري الحظر المنصوص عليه في الفقرة (ب) من هذه المادة على أي شخص يطلع او يعلم بطريقة مباشرة او غير مباشرة أو يحصل على أي معلومات تم تقديمها او تبادلها بموجب أحكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضى أي منها أثناء ممارسته لمهامه.","notes":[],"title":"سرية المعلومات","memo":"⭐ تستخدم المعلومات وفق تعليمات يصدرها رئيس الوحدة\n⭐ يحظر على رئيس الوحدة وموظفيها إفشاء المعلومات، ويستمر الحظر إلى ما بعد انتهاء عملهم\n⭐ يسري الحظر على أي شخص يطلع على المعلومات أثناء ممارسته مهامه\n⭐ عقوبة المخالفة (م31/ب): حبس لا يقل عن 6 أشهر وغرامة 5,000–10,000 دينار","qs":[{"q":"يستمر حظر إفشاء المعلومات على رئيس الوحدة وموظفيها:","o":["إلى ما بعد انتهاء عملهم في الوحدة","طوال مدة عملهم في الوحدة فقط","لمدة خمس سنوات من انتهاء عملهم","لمدة سنتين من انتهاء عملهم"],"a":0},{"q":"تستخدم المعلومات والوثائق التي تتلقاها الوحدة وفقاً لتعليمات يصدرها:","o":["رئيس الوحدة","المحافظ","اللجنة الوطنية","مجلس الوزراء"],"a":0},{"q":"حالة عملية: موظف في جهة رقابية اطلع أثناء ممارسته لمهامه على معلومات تم تبادلها بموجب هذا القانون. فإن حظر الإفشاء:","o":["يسري عليه كما يسري على رئيس الوحدة وموظفيها","لا يسري عليه لأنه ليس من موظفي الوحدة","يسري عليه فقط إذا وقع على تعهد بالسرية","يسري عليه طوال مدة خدمته فقط"],"a":0}]},{"n":"14","chapter":"","source":"أ. تلتزم الجهات المبينة أدناه بالإجراءات المنصوص عليها في هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضى أي منها:-\n1. المؤسسات المالية وتشمل:-\nاولاً: البنوك العاملة في المملكة.\nثانياً: شركات الصرافة وشركات تحويل الأموال.\nثالثاً: الأشخاص أو الشركات التي تمارس أياً من الأنشطة التي تخضع لرقابة وترخيص هيئة الأوراق المالية .\nرابعاً: شركات التأمين الحاصلة على إجازة لممارسة اعمال التأمين في المملكة ووكلاء ووسطاء التأمين.\nخامساً: الجهات التي تمارس أياً من الأنشطة المالية التالية:-\n- منح الائتمان بجميع أنواعه.\n- تقديم خدمات الدفع والتحصيل.\n- إصدار أدوات الدفع والائتمان وإدارتها.\n- الاتجار بأدوات السوق النقدي وبأدوات سوق رأس المال سواء لحسابها أو لحساب عملائها.\n- شراء الديون وبيعها سواء بحق الرجوع أو بدونه.\n- التأجير التمويلي.\n- إدارة الاستثمارات والأصول المالية عن الغير.\n- قبول الودائع.\nسادساً: الجهات التي تقدم الخدمات البريدية وفقاً لأحكام التشريعات النافذة.\n2. المهن والأعمال غير المالية التالية:-\nاولاً: الأشخاص أو الجهات الذين يعملون في تجارة العقارات وتطويرها.\nثانياً: الأشخاص أو الجهات الذين يعملون في تجارة المعادن الثمينة والأحجار الكريمة.\nثالثاً: المحامون وغيرهم من أصحاب المهن القانونية والمحاسبون القانونيون لدى قيامهم نيابة عن الغير بإعداد عمليات مالية أو تنفيذها لمصلحة عملائهم فيما يتعلق بالأعمال التالية:-\n- بيع وشراء العقارات أو المحلات التجارية.\n- إدارة الأموال أو الأوراق المالية أو أي أصول مالية أخرى.\n- إدارة الحسابات المصرفية أو حسابات توفير البريد أو حسابات الاستثمار في الأسواق المالية المحلية والدولية.\n- اتخاذ الإجراءات القانونية اللازمة لتأسيس أي شخص اعتباري أو إدارته.\n- تنظيم المساهمات المتعلقة بتأسيس الشركات أو تشغيلها أو إدارتها.\nب. لمجلس الوزراء بناء على تنسيب رئيس اللجنة أن يقرر تطبيق أحكام هذا القانون والأنظمة والتعليمات والقرارات الصادرة بمقتضى أي منها على أي جهة أو مهنة أو نشاط","notes":[],"title":"الجهات المبلغة","memo":"⭐ المؤسسات المالية: البنوك، الصرافة وتحويل الأموال، الخاضعون لهيئة الأوراق المالية، شركات التأمين ووكلاؤها ووسطاؤها، جهات الأنشطة المالية (ائتمان، دفع، تأجير تمويلي، قبول ودائع…)، الخدمات البريدية\n⭐ المهن غير المالية: تجارة العقارات وتطويرها، المعادن الثمينة والأحجار الكريمة، المحامون والمحاسبون القانونيون عند قيامهم نيابة عن الغير بعمليات مالية محددة\n⭐ لمجلس الوزراء بتنسيب رئيس اللجنة تطبيق القانون على أي جهة أو مهنة أو نشاط","qs":[{"q":"يعد المحاسب القانوني من الجهات المبلغة الخاضعة لأحكام القانون:","o":["لدى قيامه نيابة عن الغير بإعداد أو تنفيذ عمليات مالية لمصلحة عملائه في أعمال محددة كإدارة الأموال أو بيع وشراء العقارات","في جميع الأحوال وعند تدقيقه لأي بيانات مالية","فقط إذا كان يعمل لدى بنك أو شركة صرافة","فقط إذا قرر مجلس الوزراء ذلك بشأنه بالاسم"],"a":0},{"q":"أي مما يلي لا يعد من المؤسسات المالية الواردة في المادة (14)؟","o":["الأشخاص الذين يعملون في تجارة المعادن الثمينة والأحجار الكريمة","شركات الصرافة وشركات تحويل الأموال","الجهات التي تقدم الخدمات البريدية","الجهات التي تمارس التأجير التمويلي"],"a":0},{"q":"يقرر تطبيق أحكام القانون على أي جهة أو مهنة أو نشاط آخر:","o":["مجلس الوزراء بناء على تنسيب رئيس اللجنة","اللجنة الوطنية بناء على تنسيب رئيس الوحدة","المحافظ بموافقة مجلس الوزراء","الجهة الرقابية والإشرافية المختصة"],"a":0},{"q":"من الأعمال التي يخضع بموجبها المحامون والمحاسبون القانونيون لأحكام القانون عند قيامهم بها نيابة عن الغير:","o":["اتخاذ الإجراءات القانونية اللازمة لتأسيس أي شخص اعتباري أو إدارته","تقديم الاستشارات الضريبية العامة","الترافع أمام المحاكم في الدعاوى الحقوقية","تدقيق القوائم المالية السنوية للشركات"],"a":0}]},{"n":"15","chapter":"","source":"على الجهات المبلغة ووفقاً للتعليمات الصادرة لهذه الغاية والتي تراعي قدرة الجهة القيام بما يلي:-\nأ. تحديد وتقييم وفهم ومراقبة مخاطر غسل الأموال وتمويل الإرهاب لديها مع الأخذ بعين الاعتبار عوامل الخطر المتعلقة بالعملاء والدول والمناطق الجغرافية والمنتجات والخدمات وقنواتها والعمليات والتقنيات بما فيها تلك الجديدة او التي هي قيد التطوير وعلى أن يتناسب ذلك مع طبيعة وحجم الجهة المبلغة ومتطلبات السلطات الرقابية ومستوى المخاطر الوطنية.\nب. تبني وإقرار سياسات وضوابط وإجراءات لإدارة وتخفيض المخاطر وذلك بناءً على نتائج تقييم المخاطر المشار إليه في الفقرة (أ) من هذه المادة.\nج. توثيق وتحديث عمليات تقييم المخاطر الذاتي دوريا أو كلما دعت الحاجة وتوفيرها للجهات المختصة بناء على طلبها.\nد. عدم فتح أي حسابات مجهولة أو حسابات بأسماء وهمية أو الاحتفاظ بها وعدم التعامل مع مجهولي الهوية سواء أكانوا اشخاصا طبيعيين أم اعتباريين.\nهـ. اتخاذ إجراءات العناية الواجبة أو المبسطة او المشددة بما يتناسب وتقييم المخاطر والتحقق منها على ان تطبق إجراءات العناية الواجبة المشددة عند تحقق حالات محددة للمخاطر المرتفعة أو عند وجود اشتباه بغسل الأموال أو تمويل الإرهاب.\nو. اتخاذ إجراءات ملائمة لإدارة المخاطر لتحديد فيما اذا كان العميل أو المستفيد الحقيقي من الأشخاص السياسيين المعرضين للمخاطر واتخاذ اجراءات عناية خاصة بذلك .\nز. تطبيق برامج لمكافحة غسل الأموال وأي جريمة أصلية مرتبطة بها وتمويل الإرهاب بما ينسجم مع تقييم المخاطر .\nح. تلتزم المجموعة المالية بتطبيق برامج لمكافحة غسل الأموال وتمويل الإرهاب على مستوى المجموعة تتضمن سياسات وإجراءات لتبادل المعلومات بينها وعلى المؤسسة المالية الأم التحقق من ان فروعها الخارجية والشركات التابعة لها تطبق تدابير مكافحة غسل الأموال وتمويل الإرهاب المفروضة عليها.","notes":[],"title":"إدارة المخاطر والعناية الواجبة","memo":"⭐ تحديد وتقييم وفهم ومراقبة المخاطر (العملاء، الدول، المنتجات، القنوات، التقنيات) بما يتناسب مع طبيعة وحجم الجهة\n⭐ عدم فتح حسابات مجهولة أو بأسماء وهمية أو التعامل مع مجهولي الهوية\n⭐ العناية الواجبة المشددة عند المخاطر المرتفعة أو عند الاشتباه؛ وإجراءات خاصة للأشخاص السياسيين المعرضين للمخاطر\n⭐ المؤسسة المالية الأم تتحقق من تطبيق فروعها الخارجية وشركاتها التابعة للتدابير","qs":[{"q":"تطبق الجهات المبلغة إجراءات العناية الواجبة المشددة:","o":["عند تحقق حالات محددة للمخاطر المرتفعة أو عند وجود اشتباه بغسل الأموال أو تمويل الإرهاب","على جميع العملاء دون استثناء","فقط على العملاء غير الأردنيين","فقط عند طلب الوحدة ذلك خطياً"],"a":0},{"q":"أي مما يلي يتعارض مع التزامات الجهات المبلغة وفق المادة (15)؟","o":["فتح حساب بناء على طلب العميل باسم وهمي مع الاحتفاظ بهويته الحقيقية لدى الإدارة","توثيق وتحديث عمليات تقييم المخاطر الذاتي دورياً","تحديد ما إذا كان المستفيد الحقيقي من الأشخاص السياسيين المعرضين للمخاطر","تبني سياسات وضوابط لإدارة وتخفيض المخاطر بناء على نتائج تقييم المخاطر"],"a":0},{"q":"الجهة المسؤولة عن التحقق من أن الفروع الخارجية والشركات التابعة للمجموعة المالية تطبق تدابير مكافحة غسل الأموال وتمويل الإرهاب هي:","o":["المؤسسة المالية الأم","الوحدة","الجهة الرقابية في الدولة المضيفة","اللجنة الوطنية"],"a":0}]},{"n":"16","chapter":"","source":"أ. على الجهات المبلغة في حال تعذر قيامها باتخاذ اجراءات العناية أو البدء في أي من الاجراءات المنصوص عليها في الفقرة (هـ) من المادة (15) من هذا القانون عدم فتح الحساب أو تنفيذ العملية أو بدء أي من الاجراءات أو الاستمرار بأي منها ولها في ذلك إخطار الوحدة.\nب. لا تسري أحكام الفقرة (أ) من هذه المادة في حال وجود اشتباه بغسل أموال أو جريمة أصلية مرتبطة بها أو تمويل إرهاب لدى الجهة المبلغة واعتقادها وفقاً لأسباب معقولة بأن تنفيذ اجراءات العناية الواجبة من شأنه أن ينبه العميل، وللجهة المبلغة عدم مواصلة الإجراءات وتقديم اخطار للوحدة بذلك .","notes":[],"title":"تعذر إجراءات العناية الواجبة","memo":"⭐ عند تعذر العناية الواجبة: عدم فتح الحساب أو تنفيذ العملية أو بدء الإجراءات أو الاستمرار بها، ولها إخطار الوحدة\n⭐ استثناء: عند الاشتباه والاعتقاد لأسباب معقولة بأن العناية الواجبة ستنبه العميل، فللجهة عدم مواصلة الإجراءات وتقديم إخطار للوحدة","qs":[{"q":"إذا تعذر على الجهة المبلغة اتخاذ إجراءات العناية الواجبة تجاه عميل، فعليها:","o":["عدم فتح الحساب أو تنفيذ العملية أو الاستمرار بأي من الإجراءات","فتح الحساب مع تطبيق العناية المبسطة","تنفيذ العملية وإخطار الوحدة خلال خمسة أيام عمل","الحصول على موافقة الجهة الرقابية لتنفيذ العملية"],"a":0},{"q":"حالة عملية: اشتبه بنك بأن عملية مرتبطة بغسل أموال، واعتقد لأسباب معقولة أن تنفيذ إجراءات العناية الواجبة سينبه العميل. وفق القانون فللبنك:","o":["عدم مواصلة الإجراءات وتقديم إخطار للوحدة بذلك","استكمال إجراءات العناية الواجبة رغم ذلك وجوباً","إبلاغ العميل بأسباب التوقف","تنفيذ العملية دون أي إجراء آخر"],"a":0}]},{"n":"17","chapter":"","source":"أ. تحتفظ الجهات المبلغة ووفقاً لتعليمات تصدر لهذه الغاية بسجلات تتضمن ما تجريه من عمليات محلية او دولية وبالبيانات الكافية للتعرف على تلك العمليات لمدة لا تقل عن خمس سنوات من تاريخ إتمام العملية، كما يتعين عليها الاحتفاظ بجميع السجلات التي يتم الحصول عليها من خلال إجراءات العناية الواجبة وملفات الحسابات والمراسلات التجارية ونتائج أي تحليل تم إجراؤه لمدة خمس سنوات على الأقل من تاريخ انتهاء العلاقة أو العملية أيهما أطول وعلى أن تتيح آلية الاحتفاظ بهذه السجلات إمكانية إعادة تركيب العمليات الفردية وبما يوفر دليلاً لذلك.\nب. تلتزم الجهات المبلغة بتحديث السجلات بما فيها سجلات العناية الواجبة والوثائق والمستندات والبيانات والمعلومات ونتائج أي تحليل تم إجراؤه بما في ذلك سجلات العناية الواجبة المنصوص عليها في الفقرة (أ) من هذه المادة بصفة دورية، وإتاحتها للجهات المختصة بناء على طلبها.","notes":[],"title":"الاحتفاظ بالسجلات","memo":"⭐ سجلات العمليات المحلية والدولية: مدة لا تقل عن خمس سنوات من تاريخ إتمام العملية\n⭐ سجلات العناية الواجبة وملفات الحسابات والمراسلات ونتائج التحليل: خمس سنوات على الأقل من تاريخ انتهاء العلاقة أو العملية أيهما أطول\n⭐ يجب أن تتيح آلية الحفظ إعادة تركيب العمليات الفردية، مع تحديث السجلات دورياً","qs":[{"q":"تحتفظ الجهات المبلغة بسجلات العمليات المحلية أو الدولية لمدة لا تقل عن:","o":["خمس سنوات من تاريخ إتمام العملية","سبع سنوات من تاريخ إتمام العملية","عشر سنوات من تاريخ إتمام العملية","ثلاث سنوات من تاريخ إتمام العملية"],"a":0},{"q":"تحتسب مدة الاحتفاظ بسجلات العناية الواجبة وملفات الحسابات والمراسلات التجارية من تاريخ:","o":["انتهاء العلاقة أو العملية أيهما أطول","فتح الحساب","انتهاء العلاقة أو العملية أيهما أقصر","آخر تحديث للسجلات"],"a":0},{"q":"يجب أن تتيح آلية احتفاظ الجهات المبلغة بالسجلات:","o":["إمكانية إعادة تركيب العمليات الفردية وبما يوفر دليلاً لذلك","إمكانية اطلاع العميل عليها في أي وقت","إتلافها فور انتهاء العلاقة مع العميل","نقلها إلى الوحدة بشكل شهري"],"a":0}]},{"n":"18","chapter":"","source":"على الجهة المبلغة إخطار الوحدة فوراً عن أي عملية أو نشاط أو محاولة اجرائها إذا اشتبهت أو توافرت لديها أسباب معقولة للاشتباه بأن الأموال متحصلة عن جريمة غسل أموال أو جريمة أصلية مرتبطة بها أو تمويل إرهاب وبغض النظر عن قيمة العملية ووفقا لتعليمات تصدرها الوحدة.","notes":[],"title":"الإخطار عن الاشتباه","memo":"⭐ على الجهة المبلغة إخطار الوحدة فوراً عن أي عملية أو نشاط أو محاولة إجرائها عند الاشتباه أو توافر أسباب معقولة للاشتباه\n⭐ بغض النظر عن قيمة العملية، ووفق تعليمات تصدرها الوحدة\n⭐ عقوبة المخالفة (م31/ج): حبس لا يزيد على 3 سنوات أو غرامة 10,000–200,000 دينار أو كلتاهما","qs":[{"q":"يجب على الجهة المبلغة إخطار الوحدة عن العملية المشتبه بها:","o":["فوراً وبغض النظر عن قيمة العملية","خلال خمسة أيام عمل إذا تجاوزت قيمتها حداً معيناً","خلال سبعة أيام من تاريخ الاشتباه","فوراً إذا تجاوزت قيمتها عشرة آلاف دينار"],"a":0},{"q":"حالة عملية: حاول عميل إجراء عملية لدى شركة صرافة واشتبهت الشركة بأن الأموال متحصلة عن جريمة، ثم عدل العميل عن إتمام العملية. وفق القانون:","o":["تلتزم الشركة بإخطار الوحدة فوراً لأن الإخطار يشمل محاولة إجراء العملية","لا التزام على الشركة لعدم إتمام العملية","تلتزم الشركة بإخطار الجهة الرقابية فقط","تلتزم الشركة بإخطار المدعي العام مباشرة"],"a":0},{"q":"تصدر التعليمات المتعلقة بإخطار الجهات المبلغة عن العمليات المشتبه بها من قبل:","o":["الوحدة","اللجنة الوطنية","مجلس الوزراء","الجهات الرقابية والإشرافية"],"a":0}]},{"n":"19","chapter":"","source":"يحظر على الجهات المبلغة ومديريها وموظفيها وغيرهم من العاملين لديها الافصاح عن قيامهم بإخطار الوحدة او بتقديم اي معلومات متعلقة بغسل الاموال او الجريمة الاصلية المرتبطة بها أو تمويل الارهاب وتستثنى من ذلك حالات الافصاح للمديرين المعنيين او موظفي الامتثال او بين المؤسسات المالية ضمن المجموعة المالية الواحدة والجهات المخولة قانونا بالاطلاع على تلك المعلومات.","notes":[],"title":"حظر الإفصاح عن الإخطار","memo":"⭐ يحظر على الجهات المبلغة ومديريها وموظفيها الإفصاح عن قيامهم بإخطار الوحدة أو تقديم المعلومات\n⭐ يستثنى: المديرون المعنيون، موظفو الامتثال، بين المؤسسات المالية ضمن المجموعة المالية الواحدة، الجهات المخولة قانوناً\n⭐ عقوبة المخالفة (م31/ب): حبس لا يقل عن 6 أشهر وغرامة 5,000–10,000 دينار","qs":[{"q":"أي مما يلي لا يعد من الحالات المستثناة من حظر الإفصاح عن إخطار الوحدة؟","o":["الإفصاح للعميل المعني بالعملية","الإفصاح لموظفي الامتثال","الإفصاح بين المؤسسات المالية ضمن المجموعة المالية الواحدة","الإفصاح للجهات المخولة قانوناً بالاطلاع على تلك المعلومات"],"a":0},{"q":"حالة عملية: أخبر موظف في بنك عميلاً بأن البنك قد أخطر الوحدة عن عمليته. فإن عقوبته وفق القانون:","o":["الحبس مدة لا تقل عن ستة أشهر وغرامة لا تقل عن خمسة آلاف دينار ولا تزيد على عشرة آلاف دينار أو بكلتا هاتين العقوبتين","الحبس مدة لا تزيد على سنة أو غرامة من ألفي دينار إلى عشرين ألف دينار","الحبس مدة لا تزيد على ثلاث سنوات أو غرامة من عشرة آلاف إلى مائتي ألف دينار","غرامة لا تقل عن ألف دينار ولا تزيد على عشرة آلاف دينار"],"a":0}]},{"n":"20","chapter":"","source":"تنتفي المسؤولية الجزائية او المدنية او الادارية او التأديبية عن كل شخص طبيعي او معنوي عند قيامه بحسن نية بواجب الاخطار عن أي من العمليات التي يشتبه بأنها مرتبطة بجريمة غسل الاموال او الجريمة الاصلية المرتبطة بها او بتمويل الارهاب او تقديم معلومات عنها وفقاً لأحكام هذا القانون.","notes":[],"title":"الحماية عند الإخطار بحسن نية","memo":"⭐ تنتفي المسؤولية الجزائية أو المدنية أو الإدارية أو التأديبية عن كل شخص طبيعي أو معنوي\n⭐ بشرط القيام بواجب الإخطار أو تقديم المعلومات بحسن نية ووفقاً لأحكام القانون","qs":[{"q":"تنتفي المسؤولية الجزائية أو المدنية أو الإدارية أو التأديبية عن الشخص الذي يقوم بواجب الإخطار عن عملية مشتبه بها بشرط:","o":["أن يقوم بالإخطار بحسن نية ووفقاً لأحكام القانون","أن يثبت لاحقاً ارتباط العملية بجريمة","أن يحصل على موافقة العميل","أن يكون الإخطار خلال خمسة أيام عمل"],"a":0},{"q":"تشمل الحماية من المسؤولية عند الإخطار بحسن نية:","o":["كل شخص طبيعي أو معنوي يقوم بواجب الإخطار","الأشخاص الطبيعيين فقط","موظفي الامتثال في البنوك فقط","الجهات المبلغة الخاضعة لرقابة البنك المركزي فقط"],"a":0}]},{"n":"21","chapter":"","source":"لغايات تنفيذ أحكام هذا القانون، تلتزم الجهات الرقابية والإشرافية بما يلي:-\nأ. متابعة قيام الجهات المبلغة بتنفيذ التزاماتها وفقاً لأحكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه وفقا لمنهج إدارة المخاطر المحدد بمقتضى تعليمات تصدر لهذه الغاية.\nب. اجراء التفتيش المكتبي والميداني بما في ذلك فحص أي وثائق او معلومات او سجلات تعد لازمة للقيام بمهامها واعلام الجهات المبلغة التابعة لرقابتها واشرافها بنقاط الضعف في أنظمة مكافحة غسل الاموال وتمويل الارهاب في الدول الاخرى.\nج. تبني وتطبيق التدابير اللازمة لمنع المحكوم عليهم بجناية أو بجنحة متعلقة بمخالفة احكام هذا القانون من تملك حصص مسيطرة في اي مؤسسة مالية او ان يكونوا من المستفيدين الحقيقيين من هذه الحصص او يتولوا اي وظيفة من وظائف الادارة العليا فيها.\nد. التعاون وتبادل المعلومات مع الجهات النظيرة في المجالات المتعلقة بمكافحة غسل الأموال والجريمة الأصلية المرتبطة بها وتمويل الإرهاب وعلى أن لا يتم الإفصاح عن أي من المعلومات التي يتم تبادلها لطرف ثالث أو استخدامها دون الحصول على موافقة الجهة النظيرة التي قامت بتزويدها بالمعلومات، ولها في سبيل ذلك ابرام مذكرات تفاهم لتنظيم التعاون بهذا الخصوص.\nهـ. الاحتفاظ بإحصائيات متعلقة بتنفيذ أحكام هذا القانون أو الأنظمة أو القرارات الصادرة بمقتضاه بما في ذلك احصائيات التفتيش المكتبي والميداني والمخالفات المرتكبة والعقوبات المفروضة عليها .\nو. إصدار التعليمات اللازمة لتنفيذ متطلبات مكافحة غسل الأموال وتمويل الإرهاب الواردة في هذا القانون او الانظمة الصادرة بمقتضاه.","notes":[],"title":"التزامات الجهات الرقابية","memo":"⭐ متابعة التزام الجهات المبلغة وفق منهج إدارة المخاطر، وإجراء التفتيش المكتبي والميداني\n⭐ منع المحكوم عليهم بجناية أو جنحة متعلقة بالقانون من تملك حصص مسيطرة في مؤسسة مالية أو تولي الإدارة العليا فيها\n⭐ تبادل المعلومات مع الجهات النظيرة دون إفصاح لطرف ثالث إلا بموافقة الجهة المزودة، والاحتفاظ بالإحصائيات وإصدار التعليمات","qs":[{"q":"تتخذ الجهات الرقابية والإشرافية التدابير اللازمة لمنع المحكوم عليهم بجناية أو بجنحة متعلقة بمخالفة أحكام القانون من:","o":["تملك حصص مسيطرة في أي مؤسسة مالية أو تولي أي وظيفة في الإدارة العليا فيها","فتح حسابات مصرفية في المملكة","السفر خارج المملكة","التعامل مع شركات الصرافة"],"a":0},{"q":"تتابع الجهات الرقابية والإشرافية قيام الجهات المبلغة بتنفيذ التزاماتها وفقاً لـ:","o":["منهج إدارة المخاطر المحدد بمقتضى تعليمات تصدر لهذه الغاية","خطة تفتيش سنوية يقرها مجلس الوزراء","طلبات الوحدة فقط","قرارات المدعي العام المختص"],"a":0},{"q":"أي مما يلي لا يعد من التزامات الجهات الرقابية والإشرافية وفق المادة (21)؟","o":["إحالة نتائج التحليل إلى المدعي العام المختص عند وجود شبهة","إجراء التفتيش المكتبي والميداني","الاحتفاظ بإحصائيات عن المخالفات المرتكبة والعقوبات المفروضة","إصدار التعليمات اللازمة لتنفيذ متطلبات مكافحة غسل الأموال وتمويل الإرهاب"],"a":0}]},{"n":"22","chapter":"","source":"أ. على الجهات المختصة، القيام بما يلي:-\n1. تبليغ الوحدة فورا إذا تبين لها اثناء مباشرتها لاختصاصاتها وجود شبهة غسل أموال أو جريمة أصلية مرتبطة بها او تمويل إرهاب، وللوحدة إعلام هذه الجهات بالإجراءات المتخذة.\n2. اتخاذ الإجراءات والوسائل اللازمة لتبادل المعلومات والتنسيق مع الوحدة بشأن مكافحة غسل الأموال وتمويل الإرهاب.\nب. تلتزم الجهات التي تتولى انشاء وتسجيل وترخيص الاشخاص الاعتبارية الحصول على معلومات دقيقة ومحدثة ومتاحة للجهات المختصة حول المستفيدين الحقيقيين منها، ويتم الاحتفاظ بها في سجل خاص وفق تعليمات تصدرها اللجنة.","notes":[],"title":"التزامات الجهات المختصة والمستفيد الحقيقي","memo":"⭐ على الجهات المختصة تبليغ الوحدة فوراً عند تبين شبهة أثناء مباشرة اختصاصاتها، وللوحدة إعلامها بالإجراءات المتخذة\n⭐ جهات إنشاء وتسجيل وترخيص الأشخاص الاعتبارية تحصل على معلومات دقيقة ومحدثة عن المستفيدين الحقيقيين\n⭐ تحفظ في سجل خاص وفق تعليمات تصدرها اللجنة","qs":[{"q":"يحتفظ بمعلومات المستفيدين الحقيقيين من الأشخاص الاعتبارية في سجل خاص وفق تعليمات تصدرها:","o":["اللجنة الوطنية","الوحدة","دائرة مراقبة الشركات","وزارة الصناعة والتجارة والتموين"],"a":0},{"q":"إذا تبين للجهة المختصة أثناء مباشرتها لاختصاصاتها وجود شبهة غسل أموال، فعليها:","o":["تبليغ الوحدة فوراً","تبليغ اللجنة الوطنية خلال سبعة أيام","إحالة الأمر للمحكمة المختصة مباشرة","إبلاغ الجهة الرقابية خلال خمسة أيام عمل"],"a":0}]},{"n":"23","chapter":"","source":"أ. على كل شخص عند قدومه للمملكة أو مغادرته لها أن يقدم إقراراً لدائرة الجمارك عما بحوزته من مبالغ نقدية أو أدوات قابلة للتداول لحاملها والتي تتجاوز قيمتها المبلغ المحدد من اللجنة وفقاً للنموذج المعد لهذه الغاية ويطبق الإقرار على النقل المادي عبر الحدود بما فيه البريد أو الشحن.\nب. لدائرة الجمارك طلب أي معلومات عن مصدر النقد أو الأدوات القابلة للتداول لحاملها والغاية منها.\nج. تحتفظ دائرة الجمارك بالاقرارات والمعلومات ذات العلاقة وتلتزم بإتاحتها مباشرة للوحدة والجهات المختصة.","notes":[],"title":"الإقرار النقدي عبر الحدود","memo":"⭐ على كل شخص عند القدوم للمملكة أو المغادرة تقديم إقرار لدائرة الجمارك عن النقد أو الأدوات القابلة للتداول لحاملها التي تتجاوز المبلغ المحدد من اللجنة\n⭐ يطبق الإقرار على النقل المادي بما فيه البريد أو الشحن\n⭐ للجمارك طلب معلومات عن المصدر والغاية، وتتيح الإقرارات للوحدة والجهات المختصة","qs":[{"q":"يحدد المبلغ الذي يوجب تقديم الإقرار لدائرة الجمارك عن النقد والأدوات القابلة للتداول لحاملها عند القدوم أو المغادرة من قبل:","o":["اللجنة الوطنية","دائرة الجمارك","الوحدة","مجلس الوزراء"],"a":0},{"q":"يطبق الإقرار عن المبالغ النقدية والأدوات القابلة للتداول لحاملها على:","o":["النقل المادي عبر الحدود بما فيه البريد أو الشحن","المسافرين القادمين إلى المملكة فقط","المسافرين غير الأردنيين فقط","التحويلات المصرفية الإلكترونية فقط"],"a":0},{"q":"يقدم الإقرار عن المبالغ النقدية عند القدوم إلى المملكة أو المغادرة منها إلى:","o":["دائرة الجمارك","الوحدة","البنك المركزي الأردني","مديرية الأمن العام"],"a":0}]},{"n":"24","chapter":"","source":"أ. على دائرة الجمارك ضبط النقد والأدوات القابلة للتداول لحاملها في الحالات التالية:-\n1. الاشتباه بارتباطها بغسل الأموال أو الجريمة الأصلية المرتبطة بها أو تمويل الإرهاب.\n2. الإقرار الكاذب بإعطاء المعلومات.\n3. عدم قيام الشخص بتقديم الاقرار.\nب. يتعين على دائرة الجمارك إبلاغ المدعي العام المختص بالضبط الذي تم إجراؤه وفقاً لأحكام الفقرة (أ) من هذه المادة خلال مدة لا تزيد على سبعة أيام عمل للتحقق فيما إذا كانت هناك أي أدلة على جريمة غسل الأموال أو الجريمة الأصلية المرتبطة بها أو تمويل الإرهاب.\nج. على المدعي العام المختص خلال مدة لا تزيد على عشرة أيام عمل من ورود الضبط إليه إصدار قرار بشأن النقد أو الأدوات القابلة للتداول لحاملها والتي تم ضبطها وفقاً لأحكام الفقرة (أ) من هذه المادة إما بحجزها أو إعادتها وفي حال انتهاء هذه المدة دون صدور مثل هذا القرار فعلى دائرة الجمارك الافراج عن النقد أو الأدوات القابلة للتداول لحاملها موضوع الضبط وإعادتها لصاحبها.\nد. تصدر دائرة الجمارك التعليمات اللازمة لتطبيق أحكام هذه المادة والمادة (23) من هذا القانون .","notes":[],"title":"ضبط النقد على الحدود","memo":"⭐ تضبط الجمارك النقد عند: الاشتباه، الإقرار الكاذب، عدم تقديم الإقرار\n⭐ تبلغ الجمارك المدعي العام خلال مدة لا تزيد على سبعة أيام عمل\n⭐ يصدر المدعي العام قراره بالحجز أو الإعادة خلال مدة لا تزيد على عشرة أيام عمل من ورود الضبط، وإلا يفرج عن النقد ويعاد لصاحبه\n⭐ تصدر دائرة الجمارك تعليمات تطبيق المادتين (23) و(24)","qs":[{"q":"يتعين على دائرة الجمارك إبلاغ المدعي العام المختص بضبط النقد خلال مدة لا تزيد على:","o":["سبعة أيام عمل","خمسة أيام عمل","عشرة أيام عمل","ثلاثة أيام عمل"],"a":0},{"q":"على المدعي العام المختص إصدار قراره بشأن النقد المضبوط من الجمارك بحجزه أو إعادته خلال مدة لا تزيد على:","o":["عشرة أيام عمل من ورود الضبط إليه","سبعة أيام عمل من ورود الضبط إليه","خمسة أيام عمل من ورود الضبط إليه","ثلاثين يوماً من ورود الضبط إليه"],"a":0},{"q":"حالة عملية: ضبطت الجمارك نقداً مع مسافر لم يقدم إقراراً، وأبلغت المدعي العام، وانقضت المدة القانونية دون صدور قرار منه. وفق القانون:","o":["تفرج دائرة الجمارك عن النقد وتعيده لصاحبه","يعتبر النقد محجوزاً حكماً","يحال النقد إلى الوحدة","يصادر النقد لصالح الخزينة"],"a":0},{"q":"أي مما يلي لا يعد من حالات ضبط النقد من قبل دائرة الجمارك؟","o":["تجاوز النقد المصرح عنه ضعف المبلغ المحدد من اللجنة","الاشتباه بارتباطه بغسل الأموال أو تمويل الإرهاب","الإقرار الكاذب بإعطاء المعلومات","عدم قيام الشخص بتقديم الإقرار"],"a":0}]},{"n":"25","chapter":"","source":"على الوحدة إعلام الجهات الرقابية والإشرافية بأي مخالفات ترتكبها الجهات المبلغة لأي من أحكام هذا القانون او الانظمة او التعليمات او القرارات الصادرة بمقتضاه ويتعين على الجهة الرقابية والإشرافية إعلام الوحدة بالإجراء المتخذ من قبلها .","notes":[],"title":"إعلام الرقابيين بالمخالفات","memo":"⭐ على الوحدة إعلام الجهات الرقابية والإشرافية بأي مخالفات ترتكبها الجهات المبلغة\n⭐ على الجهة الرقابية والإشرافية إعلام الوحدة بالإجراء المتخذ من قبلها","qs":[{"q":"إذا تبين للوحدة ارتكاب جهة مبلغة مخالفة لأحكام القانون، فعليها إعلام:","o":["الجهات الرقابية والإشرافية","المدعي العام المختص","مجلس الوزراء","اللجنة الوطنية"],"a":0},{"q":"بعد إعلام الوحدة للجهة الرقابية والإشرافية بمخالفة إحدى الجهات المبلغة، يتعين على الجهة الرقابية:","o":["إعلام الوحدة بالإجراء المتخذ من قبلها","إحالة المخالفة للمحكمة فوراً","إعلام اللجنة الوطنية فقط","إلغاء ترخيص الجهة المبلغة"],"a":0}]},{"n":"26","chapter":"","source":"أ. تمارس النيابة العامة او المحكمة المختصة اختصاصاتها في الجرائم المنصوص عليها في هذا القانون وفق قانون أصول المحاكمات الجزائية ولها القيام بأي مما يلي:-\n1. تحديد وتتبع المتحصلات والأموال والوسائط والادوات المستخدمة أو التي كان من المنوي استخدامها في ارتكاب أي من الجرائم الواردة في هذا القانون وحجزها.\n2. حجز ممتلكات اختلطت فيها المتحصلات مع أموال من مصادر مشروعة الى ان تحدد قيمة المتحصلات غير المشروعة ونواتج استغلالها.\n3. حجز أموال المشتكى عليه بالجرائم المنصوص عليها في هذا القانون أو أي تشريع آخر ذي علاقة ومنعه من السفر الى حين استكمال اجراءات التحقيق او الفصل في الدعوى .\n4. حجز أي مال لدى الغير إذا تبين انه قد تم الحصول عليه نتيجة ارتكاب أي من الجرائم المنصوص عليها في هذا القانون.\n5. طلب السجلات والوثائق والمستندات والبيانات من الجهات الخاضعة لأحكام هذا القانون لغايات التحقيق في الجرائم المنصوص عليها فيه .\nب. للمتضرر من الإجراءات المنصوص عليها في البنود من (1) الى (4) من الفقرة (أ) من هذه المادة حق الطعن خلال سبعة أيام من تاريخ صدور قرار الحجز لدى المحكمة المختصة.\nج. على الرغم مما ورد في اي تشريع آخر، يترتب على حجز الأموال الذي يجريه المدعي العام او المحكمة المختصة وفق أحكام هذا القانون وقف جميع الاجراءات والمعاملات الجارية على ذلك المال.","notes":[],"title":"صلاحيات النيابة في الحجز","memo":"⭐ للنيابة أو المحكمة تتبع وحجز المتحصلات والوسائط، وحجز الممتلكات المختلطة، وحجز أموال المشتكى عليه ومنعه من السفر، وحجز المال لدى الغير، وطلب السجلات\n⭐ للمتضرر من إجراءات البنود (1)-(4) الطعن خلال سبعة أيام من تاريخ صدور قرار الحجز لدى المحكمة المختصة\n⭐ يترتب على الحجز وقف جميع الإجراءات والمعاملات الجارية على المال رغم أي تشريع آخر","qs":[{"q":"للمتضرر من قرار حجز الأموال الصادر وفق المادة (26) حق الطعن لدى المحكمة المختصة خلال:","o":["سبعة أيام من تاريخ صدور قرار الحجز","عشرة أيام من تاريخ صدور قرار الحجز","ثلاثين يوماً من تاريخ تبليغه قرار الحجز","خمسة أيام عمل من تاريخ صدور قرار الحجز"],"a":0},{"q":"يترتب على حجز الأموال الذي يجريه المدعي العام أو المحكمة المختصة وفق أحكام القانون:","o":["وقف جميع الإجراءات والمعاملات الجارية على ذلك المال","مصادرة المال حكماً","نقل ملكية المال إلى الخزينة","تجميد المال لمدة خمسة أيام عمل فقط"],"a":0},{"q":"يجوز للنيابة العامة حجز الممتلكات التي اختلطت فيها المتحصلات مع أموال من مصادر مشروعة:","o":["إلى أن تحدد قيمة المتحصلات غير المشروعة ونواتج استغلالها","لمدة لا تزيد على سنة","بعد صدور حكم قطعي بالإدانة فقط","بموافقة الوحدة"],"a":0}]},{"n":"27","chapter":"","source":"ينشأ مكتب لإدارة الاموال والاصول المحجوزة والمصادرة بموجب احكام هذا القانون يتبع للنائب العام في عمان ويرأسه مدع عام وتحدد مهام المكتب وصلاحياته وكيفية ادارته وسائر الشؤون المتعلقة به بمقتضى نظام يصدر لهذه الغاية.","notes":[],"title":"مكتب إدارة الأموال المحجوزة","memo":"⭐ ينشأ مكتب لإدارة الأموال والأصول المحجوزة والمصادرة يتبع للنائب العام في عمان\n⭐ يرأسه مدع عام، وتحدد مهامه وصلاحياته بنظام","qs":[{"q":"يتبع مكتب إدارة الأموال والأصول المحجوزة والمصادرة لـ:","o":["النائب العام في عمان","وحدة مكافحة غسل الأموال وتمويل الإرهاب","وزارة المالية","البنك المركزي الأردني"],"a":0},{"q":"يرأس مكتب إدارة الأموال والأصول المحجوزة والمصادرة:","o":["مدع عام","رئيس الوحدة","قاض يسميه المجلس القضائي","مدير عام دائرة الجمارك"],"a":0}]},{"n":"28","chapter":"","source":"لغايات هذا القانون، يسمي رئيس المجلس القضائي مدعيا عاما متخصصا أو أكثر للنظر في قضايا غسل الأموال، ويسمي النائب العام لمحكمة أمن الدولة مدعيا عاما متخصصا أو أكثر للنظر في قضايا تمويل الإرهاب.","notes":[],"title":"المدعي العام المتخصص","memo":"⭐ رئيس المجلس القضائي يسمي مدعياً عاماً متخصصاً أو أكثر لقضايا غسل الأموال\n⭐ النائب العام لمحكمة أمن الدولة يسمي مدعياً عاماً متخصصاً أو أكثر لقضايا تمويل الإرهاب","qs":[{"q":"يسمي المدعي العام المتخصص للنظر في قضايا غسل الأموال:","o":["رئيس المجلس القضائي","النائب العام لمحكمة أمن الدولة","وزير العدل","رئيس اللجنة الوطنية"],"a":0},{"q":"يسمي المدعي العام المتخصص للنظر في قضايا تمويل الإرهاب:","o":["النائب العام لمحكمة أمن الدولة","رئيس المجلس القضائي","النائب العام في عمان","وزير الداخلية"],"a":0}]},{"n":"29","chapter":"","source":"إضافة الى الصلاحيات التي تمارسها الجهات التي تتولى التحقيق او الادعاء في قضايا غسل الأموال والجرائم الاصلية المرتبطة بها وتمويل الارهاب وفق قانون اصول المحاكمات الجزائية أو أي تشريع آخر ذي علاقة، تتولى القيام بما يلي:-\nأ. إجراء التحقيقات المالية الموازية مباشرة أو من خلال إحالتها إلى أي جهة أخرى.\nب. طلب المعلومات الموجودة في قاعدة بيانات الوحدة أثناء قيامها بإجراء التحقيقات ذات العلاقة بغسل الأموال والجريمة الأصلية المرتبطة بها وتمويل الإرهاب.\nج. تشكيل فرق تحقيق مشتركة دائمة أو مؤقتة لإجراء تحقيقات متخصصة بما في ذلك إجراء التحقيقات المالية أو التحري عن الأصول أو إجراء تحقيقات مشتركة مع السلطات المختصة في الدول الأخرى.\nد. تبادل المعلومات المتوافرة لديها مع الجهات النظيرة لأغراض التحريات والتحقيقات المتعلقة بغسل الأموال أو الجريمة الأصلية المرتبطة بها أو تمويل الإرهاب بما يشمل تحديد المتحصلات والوسائط والادوات الإجرامية وتعقبها.","notes":[],"title":"التحقيقات المالية الموازية","memo":"⭐ لجهات التحقيق والادعاء إجراء التحقيقات المالية الموازية مباشرة أو بإحالتها لجهة أخرى\n⭐ طلب المعلومات من قاعدة بيانات الوحدة، وتشكيل فرق تحقيق مشتركة دائمة أو مؤقتة\n⭐ تبادل المعلومات مع الجهات النظيرة لتحديد المتحصلات وتعقبها","qs":[{"q":"لجهات التحقيق والادعاء في قضايا غسل الأموال إجراء التحقيقات المالية الموازية:","o":["مباشرة أو من خلال إحالتها إلى أي جهة أخرى","مباشرة فقط","من خلال الوحدة حصراً","بعد موافقة المحكمة المختصة"],"a":0},{"q":"فرق التحقيق المشتركة التي يجوز لجهات التحقيق والادعاء تشكيلها وفق المادة (29) تكون:","o":["دائمة أو مؤقتة","مؤقتة فقط ولمدة لا تزيد على سنة","دائمة فقط بقرار من مجلس الوزراء","مؤقتة بموافقة اللجنة الوطنية"],"a":0}]},{"n":"30","chapter":"","source":"أ. مع عدم الاخلال بأي عقوبة أشد ورد النص عليها في أي قانون آخر، يعاقب كل من ارتكب أو شرع او تدخل او شارك او حرض او تآمر في ارتكاب جريمة غسل الأموال أو تمويل الارهاب المنصوص عليهما في هذا القانون بالأشغال المؤقتة وبغرامة لا تقل عن مثل الأموال محل الجريمة ومصادرة متحصلاتها وايراداتها ومنافعها وأي وسائط أو أدوات استخدمت أو كان من المنوي استخدامها في الجريمة وذلك مع مراعاة حقوق الغير حسن النية.\nب. يحكم في جميع الأحوال بالمصادرة العينية للمتحصلات أو باموال تعادلها في القيمة في حال تعذر ضبطها او التنفيذ عليها او في حال التصرف فيها إلى الغير حسن النية.\nج. إذا اختلطت المتحصلات باموال اكتسبت من مصادر مشروعة فتخضع هذه الأموال للمصادرة المنصوص عليها في الفقرة (ب) من هذه المادة في حدود القيمة المقدرة للمتحصلات وإيراداتها ومنافعها.","notes":[],"title":"عقوبة غسل الأموال وتمويل الإرهاب","memo":"⭐ الأشغال المؤقتة وغرامة لا تقل عن مثل الأموال محل الجريمة، مع مصادرة المتحصلات والإيرادات والمنافع والوسائط مع مراعاة حقوق الغير حسن النية\n⭐ تشمل العقوبة من ارتكب أو شرع أو تدخل أو شارك أو حرض أو تآمر\n⭐ يحكم في جميع الأحوال بالمصادرة العينية أو بأموال تعادلها في القيمة عند تعذر الضبط أو التصرف للغير حسن النية\n⭐ المتحصلات المختلطة بأموال مشروعة تصادر في حدود القيمة المقدرة للمتحصلات","qs":[{"q":"يعاقب مرتكب جريمة غسل الأموال أو تمويل الإرهاب وفق المادة (30) بـ:","o":["الأشغال المؤقتة وبغرامة لا تقل عن مثل الأموال محل الجريمة","الحبس مدة لا تزيد على ثلاث سنوات وغرامة لا تقل عن مائة ألف دينار","الأشغال المؤبدة وغرامة لا تقل عن ضعف الأموال محل الجريمة","الحبس مدة لا تقل عن سنة وغرامة لا تزيد على خمسمائة ألف دينار"],"a":0},{"q":"في حال تعذر ضبط متحصلات جريمة غسل الأموال أو التصرف فيها إلى الغير حسن النية، فإن المحكمة تحكم:","o":["بمصادرة أموال تعادلها في القيمة","بإسقاط المصادرة","بمضاعفة الغرامة فقط","بحبس المحكوم عليه بدلاً من المصادرة"],"a":0},{"q":"حالة عملية: اختلطت متحصلات جريمة غسل أموال مع أموال اكتسبت من مصادر مشروعة. وفق القانون تخضع هذه الأموال للمصادرة:","o":["في حدود القيمة المقدرة للمتحصلات وإيراداتها ومنافعها","بكامل قيمتها بما فيها الأموال المشروعة","بنسبة (50%) من قيمتها","بعد موافقة الوحدة فقط"],"a":0}]},{"n":"31","chapter":"","source":"أ. يعاقب بالحبس مدة لا تزيد على سنة او بغرامة لا تقل عن الفي دينار ولا تزيد على عشرين ألف دينار او بكلتا هاتين العقوبتين، كل من يخالف أحكام المادة (10) والمواد من (15) الى (17) والبند (5) من الفقرة (أ) من المادة (26) من هذا القانون.\nب. يعاقب بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تقل عن خمسة آلاف دينار ولا تزيد على عشرة آلاف دينار أو بكلتا هاتين العقوبتين كل من يخالف أحكام الفقرتين (ب) و(ج) من المادة (13) والمادة (19) من هذا القانون.\nج. يعاقب بالحبس مدة لا تزيد على ثلاث سنوات او بغرامة لا تقل عن عشرة آلاف دينار ولا تزيد على مائتي ألف دينار او بكلتا هاتين العقوبتين كل من يخالف أحكام المادة (18) من هذا القانون.\nد. يعاقب بغرامة لا تقل عن (10%) من قيمة النقد أو الأدوات القابلة للتداول لحاملها غير المصرح عنها او المقدم بخصوصها اقرار كاذب خلافا لأحكام الفقرة (أ) من المادة (23) من هذا القانون، وتضاعف الغرامة في حال تكرار المخالفة.","notes":[],"title":"عقوبات مخالفات محددة","memo":"⭐ مخالفة م10 والمواد 15-17 والبند 5 من م26/أ: حبس لا يزيد على سنة أو غرامة 2,000–20,000 دينار أو كلتاهما\n⭐ مخالفة م13/ب،ج وم19: حبس لا يقل عن 6 أشهر وغرامة 5,000–10,000 دينار أو كلتاهما\n⭐ مخالفة م18 (الإخطار): حبس لا يزيد على 3 سنوات أو غرامة 10,000–200,000 دينار أو كلتاهما\n⭐ عدم التصريح أو الإقرار الكاذب (م23/أ): غرامة لا تقل عن 10% من القيمة وتضاعف عند التكرار","qs":[{"q":"يعاقب من يخالف حكم الإخطار عن العمليات المشتبه بها (المادة 18) بالحبس مدة لا تزيد على ثلاث سنوات أو بغرامة:","o":["لا تقل عن عشرة آلاف دينار ولا تزيد على مائتي ألف دينار","لا تقل عن ألفي دينار ولا تزيد على عشرين ألف دينار","لا تقل عن خمسة آلاف دينار ولا تزيد على عشرة آلاف دينار","لا تقل عن مائة ألف دينار"],"a":0},{"q":"يعاقب من لم يصرح عن النقد الذي بحوزته عند عبور الحدود أو قدم إقراراً كاذباً بغرامة لا تقل عن:","o":["(10%) من قيمة النقد أو الأدوات غير المصرح عنها","(20%) من قيمة النقد أو الأدوات غير المصرح عنها","(5%) من قيمة النقد أو الأدوات غير المصرح عنها","مثل قيمة النقد أو الأدوات غير المصرح عنها"],"a":0},{"q":"حالة عملية: لم تحتفظ شركة صرافة بسجلات العمليات للمدة المطلوبة قانوناً (مخالفة المادة 17). فإن العقوبة المقررة:","o":["الحبس مدة لا تزيد على سنة أو غرامة لا تقل عن ألفي دينار ولا تزيد على عشرين ألف دينار أو بكلتا هاتين العقوبتين","الحبس مدة لا تقل عن ستة أشهر وغرامة من خمسة آلاف إلى عشرة آلاف دينار","الحبس مدة لا تزيد على ثلاث سنوات أو غرامة من عشرة آلاف إلى مائتي ألف دينار","غرامة لا تقل عن خمسة آلاف دينار ولا تزيد على عشرين ألف دينار"],"a":0},{"q":"في حال تكرار مخالفة عدم التصريح عن النقد عبر الحدود أو تقديم إقرار كاذب بشأنه:","o":["تضاعف الغرامة","تضاف عقوبة الحبس وجوباً","يصادر النقد كاملاً","يمنع الشخص من السفر"],"a":0}]},{"n":"32","chapter":"","source":"أ. مع عدم الاخلال بأي عقوبة أشد ورد النص عليها في أي قانون آخر، وفي الأحوال التي ترتكب فيها جريمة غسل الأموال أو جريمة تمويل الإرهاب من شخص اعتباري من خلال أي من الأشخاص المسؤولين عن إدارته الفعلية أو المخولين بممارسة السلطة فيه عند قيامهم بأي أفعال بالنيابة عنه أو باستخدام أي من وسائله، ودون الاخلال بمسؤولية الجناة من الأشخاص الطبيعيين، يكون الشخص الاعتباري مسؤولاً عن تلك الجرائم ويعاقب بغرامة لا تقل عن ضعف قيمة الأموال محل الجريمة وعلى ان لا تزيد على خمسمائة ألف دينار مع مصادرة متحصلات الجريمة وايراداتها ومنافعها وأي وسائط أو أدوات استخدمت أو كان من المنوي استخدامها في ارتكاب الجريمة ويكون مسؤولا عن الوفاء بها وتضاعف الغرامة في حال التكرار.\nب. مع مراعاة احكام قانون البنوك والتشريعات الاخرى للمحكمة وقف الشخص الاعتباري عن العمل كليا او جزئيا مدة لا تقل عن شهر ولا تزيد على سنة اذا ارتكب ايا من الجرائم المنصوص عليها في هذا القانون وفي حال التكرار لها ان تقرر الغاء تسجيل الشخص الاعتباري او تصفيته وفي جميع الحالات تأمر المحكمة بعد صدور الحكم القطعي بالادانة بنشره على نفقة الشخص الاعتباري في صحيفتين يوميتين محليتين من الصحف الاوسع انتشاراً.\nج. يحظر على المشار اليهم في الفقرة (أ) من هذه المادة ممن ثبتت مسؤوليتهم شخصياً عن ارتكاب أي من الجرائم المنصوص عليها في هذا القانون المشاركة أو المساهمة في رأسمال أي شخص اعتباري أو الاشتراك في إدارته.","notes":[],"title":"مسؤولية الشخص الاعتباري","memo":"⭐ غرامة لا تقل عن ضعف قيمة الأموال محل الجريمة ولا تزيد على 500,000 دينار مع المصادرة، وتضاعف عند التكرار، دون الإخلال بمسؤولية الأشخاص الطبيعيين\n⭐ للمحكمة وقفه عن العمل كلياً أو جزئياً من شهر إلى سنة، وعند التكرار إلغاء تسجيله أو تصفيته\n⭐ ينشر الحكم القطعي على نفقته في صحيفتين يوميتين محليتين من الأوسع انتشاراً\n⭐ يحظر على المسؤولين شخصياً المساهمة في رأسمال أي شخص اعتباري أو الاشتراك في إدارته","qs":[{"q":"يعاقب الشخص الاعتباري المسؤول عن جريمة غسل الأموال أو تمويل الإرهاب بغرامة:","o":["لا تقل عن ضعف قيمة الأموال محل الجريمة ولا تزيد على خمسمائة ألف دينار","لا تقل عن مثل قيمة الأموال محل الجريمة ولا تزيد على مائتي ألف دينار","لا تقل عن مائة ألف دينار ولا تزيد على مليون دينار","لا تقل عن (10%) من قيمة الأموال محل الجريمة"],"a":0},{"q":"للمحكمة وقف الشخص الاعتباري عن العمل كلياً أو جزئياً إذا ارتكب أياً من جرائم هذا القانون مدة:","o":["لا تقل عن شهر ولا تزيد على سنة","لا تقل عن ثلاثة أشهر ولا تزيد على سنتين","لا تقل عن أسبوع ولا تزيد على ستة أشهر","لا تزيد على خمسة أيام عمل"],"a":0},{"q":"في حال تكرار الشخص الاعتباري ارتكاب أي من جرائم هذا القانون، فللمحكمة أن تقرر:","o":["إلغاء تسجيل الشخص الاعتباري أو تصفيته","وقفه عن العمل مدة لا تزيد على شهر فقط","الاكتفاء بتوجيه تنبيه خطي له","نقل ملكيته إلى الدولة"],"a":0},{"q":"تأمر المحكمة بعد صدور الحكم القطعي بإدانة الشخص الاعتباري بنشره:","o":["على نفقة الشخص الاعتباري في صحيفتين يوميتين محليتين من الصحف الأوسع انتشاراً","على نفقة الخزينة في الجريدة الرسمية","على نفقة الشخص الاعتباري في صحيفة يومية واحدة","على الموقع الإلكتروني للوحدة فقط"],"a":0}]},{"n":"33","chapter":"","source":"أ.1. إذا قام أحد الأشخاص المتورطين بارتكاب جريمة غسل الأموال أو جريمة تمويل الإرهاب بإبلاغ السلطات المختصة عن الجريمة قبل علمها بها، وأدى إبلاغه إلى القبض على المساهمين في الجريمة أو ضبط المتحصلات أو منع وقوع العمل الإرهابي أو تخفيف الآثار المترتبة عليه فيعفى من العقوبة المنصوص عليها في هذا القانون.\n2. للمحكمة المختصة الإعفاء من العقوبة المشار اليها في البند (1) من هذه الفقرة في حال تم الإبلاغ عن الجريمة بعد علم الجهات المختصة بها، وأدى الإبلاغ إلى القبض على المساهمين في الجريمة أو ضبط المتحصلات أو منع وقوع العمل الإرهابي أو تخفيف الآثار المترتبة عليه.\nب. لا يحول الإعفاء من العقوبة وفقاً لأحكام الفقرة (أ) من هذه المادة من مصادرة متحصلات الجريمة أو ايراداتها ومنافعها أو وسائطها وأدواتها.","notes":[],"title":"الإعفاء من العقوبة","memo":"⭐ يعفى وجوباً من العقوبة المتورط الذي يبلغ السلطات قبل علمها بالجريمة إذا أدى إبلاغه إلى القبض على المساهمين أو ضبط المتحصلات أو منع العمل الإرهابي أو تخفيف آثاره\n⭐ إذا كان الإبلاغ بعد علم الجهات المختصة: الإعفاء جوازي للمحكمة\n⭐ الإعفاء لا يمنع مصادرة المتحصلات وإيراداتها ومنافعها ووسائطها","qs":[{"q":"حالة عملية: أبلغ أحد المتورطين في جريمة غسل أموال السلطات المختصة عن الجريمة قبل علمها بها، وأدى إبلاغه إلى ضبط المتحصلات. وفق القانون:","o":["يعفى من العقوبة المنصوص عليها في القانون","يجوز للمحكمة تخفيف العقوبة إلى النصف","يعفى من العقوبة ومن المصادرة معاً","لا أثر لإبلاغه على العقوبة"],"a":0},{"q":"إذا تم الإبلاغ عن جريمة تمويل الإرهاب بعد علم الجهات المختصة بها وأدى إلى القبض على المساهمين فيها، فإن:","o":["للمحكمة المختصة الإعفاء من العقوبة","المبلغ يعفى من العقوبة وجوباً","المبلغ لا يستفيد من أي إعفاء","الإعفاء يكون بقرار من المدعي العام"],"a":0},{"q":"الإعفاء من العقوبة وفق المادة (33):","o":["لا يحول دون مصادرة متحصلات الجريمة أو إيراداتها ومنافعها أو وسائطها وأدواتها","يمنع مصادرة المتحصلات","يمنع مصادرة الوسائط والأدوات فقط","يستتبع إعادة المتحصلات للمبلغ"],"a":0}]},{"n":"34","chapter":"","source":"أ. مع عدم الإخلال بأحكام أي تشريع آخر، للجهات الرقابية والإشرافية أن تتخذ إجراء أو أكثر أو أن تفرض أيا من الجزاءات المبينة أدناه في حال تبين لها وقوع مخالفة لأحكام المادة (10) والمواد من (15) الى (17) والبند (5) من الفقرة (أ) من المادة (26) و المادة (41) من هذا القانون وذلك وفقا لدرجة خطورة تلك المخالفة:-\n1. توجيه تنبيه خطي.\n2. الطلب من الجهة المبلغة تقديم برنامج عمل لما سيتم اتخاذه من إجراءات لإزالة المخالفة وتصويب الوضع.\n3. وقف بعض أنشطة الجهة المبلغة بشكل دائم أو مؤقت.\n4. فرض غرامة لا تتجاوز مائة ألف دينار في حال عدم الإحالة على المحكمة.\n5. الطلب من الجهة المبلغة إيقاف أي من إدارييها من غير أعضاء مجلس الإدارة عن العمل أو فصله.\n6. ايقاف ترخيص الجهة المبلغة.\n7. إلغاء ترخيص أو تسجيل الجهة المبلغة.\nب. لكل ذي مصلحة الطعن في أي من الإجراءات أو الجزاءات المتخذة بمقتضى أحكام الفقرة (أ) من هذه المادة أمام المحكمة المختصة .","notes":[],"title":"الجزاءات الرقابية","memo":"⭐ للجهات الرقابية فرض جزاءات عند مخالفة م10 والمواد 15-17 والبند 5 من م26/أ وم41، وفقاً لدرجة خطورة المخالفة\n⭐ الجزاءات: تنبيه خطي، برنامج عمل للتصويب، وقف بعض الأنشطة، غرامة لا تتجاوز 100,000 دينار عند عدم الإحالة للمحكمة، إيقاف أو فصل إداري من غير أعضاء مجلس الإدارة، إيقاف الترخيص، إلغاء الترخيص أو التسجيل\n⭐ لكل ذي مصلحة الطعن أمام المحكمة المختصة","qs":[{"q":"الحد الأعلى للغرامة التي يجوز للجهة الرقابية والإشرافية فرضها على الجهة المبلغة المخالفة في حال عدم الإحالة على المحكمة هو:","o":["مائة ألف دينار","مائتا ألف دينار","عشرون ألف دينار","خمسمائة ألف دينار"],"a":0},{"q":"أي مما يلي لا يعد من الجزاءات التي يجوز للجهات الرقابية والإشرافية فرضها وفق المادة (34)؟","o":["حبس المدير المسؤول في الجهة المبلغة","توجيه تنبيه خطي","وقف بعض أنشطة الجهة المبلغة بشكل دائم أو مؤقت","إلغاء ترخيص أو تسجيل الجهة المبلغة"],"a":0},{"q":"يجوز للجهة الرقابية أن تطلب من الجهة المبلغة إيقاف أو فصل أي من إدارييها:","o":["من غير أعضاء مجلس الإدارة","بمن فيهم رئيس وأعضاء مجلس الإدارة","من أعضاء مجلس الإدارة فقط","بعد صدور حكم قطعي بإدانته فقط"],"a":0}]},{"n":"35","chapter":"","source":"إذا امتنعت او تخلفت خلال المدة المحددة أي من الجهات المبلغة عن تزويد الوحدة بالمعلومات والبيانات والوثائق والمستندات الواجب تقديمها وفقاً لأحكام هذا القانون والأنظمة والتعليمات والقرارات الصادرة بمقتضاه او عرقلت الوحدة عن تنفيذ مهامها وصلاحياتها، تفرض عليها غرامة لا تقل عن خمسة آلاف دينار ولا تزيد على عشرين الف دينار وتضاعف الغرامة في حال التكرار.","notes":[],"title":"عدم تزويد الوحدة بالمعلومات","memo":"⭐ امتناع أو تخلف الجهة المبلغة خلال المدة المحددة عن تزويد الوحدة بالمعلومات أو عرقلة مهامها\n⭐ غرامة لا تقل عن 5,000 دينار ولا تزيد على 20,000 دينار، وتضاعف عند التكرار","qs":[{"q":"تفرض على الجهة المبلغة التي تمتنع عن تزويد الوحدة بالمعلومات خلال المدة المحددة أو تعرقل مهامها غرامة:","o":["لا تقل عن خمسة آلاف دينار ولا تزيد على عشرين ألف دينار","لا تقل عن ألف دينار ولا تزيد على عشرة آلاف دينار","لا تقل عن ألفي دينار ولا تزيد على عشرين ألف دينار","لا تقل عن عشرة آلاف دينار ولا تزيد على مائتي ألف دينار"],"a":0},{"q":"في حال تكرار الجهة المبلغة الامتناع عن تزويد الوحدة بالمعلومات المطلوبة:","o":["تضاعف الغرامة","يلغى ترخيصها حكماً","تعاقب بالحبس وجوباً","توقف عن العمل مدة سنة"],"a":0}]},{"n":"36","chapter":"","source":"كل مخالفة لأي حكم من أحكام هذا القانون أو الأنظمة أو التعليمات أو القرارات الصادرة بمقتضاه لم ينص القانون على عقوبة خاصة لها، يعاقب مرتكبها بغرامة لا تقل عن ألف دينار ولا تزيد على عشرة آلاف دينار وتضاعف الغرامة في حال التكرار.","notes":[],"title":"المخالفة دون عقوبة خاصة","memo":"⭐ كل مخالفة لأحكام القانون أو أنظمته أو تعليماته لم ينص على عقوبة خاصة لها: غرامة لا تقل عن 1,000 دينار ولا تزيد على 10,000 دينار\n⭐ تضاعف الغرامة عند التكرار","qs":[{"q":"يعاقب مرتكب أي مخالفة لأحكام القانون أو الأنظمة أو التعليمات الصادرة بمقتضاه لم ينص القانون على عقوبة خاصة لها بغرامة:","o":["لا تقل عن ألف دينار ولا تزيد على عشرة آلاف دينار","لا تقل عن خمسة آلاف دينار ولا تزيد على عشرين ألف دينار","لا تقل عن ألفي دينار ولا تزيد على عشرين ألف دينار","لا تقل عن خمسمائة دينار ولا تزيد على خمسة آلاف دينار"],"a":0},{"q":"في حال تكرار المخالفة التي لم ينص القانون على عقوبة خاصة لها:","o":["تضاعف الغرامة","يضاف إليها الحبس مدة لا تزيد على سنة","تحال المخالفة للجنة الوطنية","لا يترتب أي أثر إضافي"],"a":0}]},{"n":"37","chapter":"","source":"لا يحول القرار الصادر بإسقاط دعوى الحق العام أو بوقف الملاحقة أو الإعفاء من العقوبة دون مصادرة الأموال المتحصلة عن جرائم غسل الأموال والجرائم الأصلية المرتبطة بها وتمويل الإرهاب بقرار قضائي.","notes":[],"title":"المصادرة رغم إسقاط الدعوى","memo":"⭐ لا يحول إسقاط دعوى الحق العام أو وقف الملاحقة أو الإعفاء من العقوبة دون مصادرة الأموال المتحصلة بقرار قضائي","qs":[{"q":"صدر قرار بإسقاط دعوى الحق العام في قضية غسل أموال. وفق القانون، فإن ذلك:","o":["لا يحول دون مصادرة الأموال المتحصلة عن الجريمة بقرار قضائي","يمنع مصادرة الأموال المتحصلة","يوجب إعادة الأموال المحجوزة إلى المشتكى عليه فوراً","يحول دون المصادرة إلا بموافقة الوحدة"],"a":0},{"q":"تتم مصادرة الأموال المتحصلة عن جرائم غسل الأموال وتمويل الإرهاب رغم إسقاط دعوى الحق العام أو وقف الملاحقة بموجب:","o":["قرار قضائي","قرار من الوحدة","قرار من الجهة الرقابية والإشرافية","قرار من مجلس الوزراء"],"a":0}]},{"n":"38","chapter":"","source":"أ. تتعاون الجهات القضائية والجهات المختصة مع الجهات غير الاردنية بالمساعدة القانونية المتبادلة في التحقيقات والادعاءات وسماع الشهود والاجراءات المتعلقة بمكافحة غسل الأموال والجريمة الأصلية المرتبطة بها وتمويل الإرهاب.\nب. يشمل التعاون الدولي طلبات تسليم المتهمين والمحكوم عليهم وكذلك طلبات الجهات غير الاردنية تعقب او تجميد او التحفظ على الأموال محل جرائم غسل الأموال أو الجريمة الأصلية المرتبطة بها او تمويل الإرهاب او متحصلات أي منها أو أي إجراءات أخرى وذلك وفق القواعد التي تحددها القوانين المعمول بها في المملكة والاتفاقيات الثنائية او المتعددة الاطراف التي صادقت عليها المملكة او وفقا لمبدأ المعاملة بالمثل ومع عدم الاخلال بحقوق الغير حسن النية.\nج. إذا تعلق طلب المساعدة القانونية المتبادلة بإجراءات غير قسرية، فلا يتم إعمال مبدأ ازدواجية التجريم كشرط للمساعدة القانونية المتبادلة .\nد. تكون وزارة العدل الجهة المعنية في المملكة لغايات تنفيذ طلبات المساعدة القانونية المتبادلة وغيرها من طلبات التعاون الدولي.","notes":[],"title":"المساعدة القانونية والتعاون الدولي","memo":"⭐ تتعاون الجهات القضائية والمختصة مع الجهات غير الأردنية بالمساعدة القانونية المتبادلة\n⭐ يشمل التعاون تسليم المتهمين والمحكوم عليهم وطلبات تعقب أو تجميد الأموال، وفق القوانين والاتفاقيات أو مبدأ المعاملة بالمثل\n⭐ لا يعمل بمبدأ ازدواجية التجريم إذا تعلق الطلب بإجراءات غير قسرية\n⭐ وزارة العدل هي الجهة المعنية بتنفيذ طلبات المساعدة القانونية","qs":[{"q":"الجهة المعنية في المملكة لغايات تنفيذ طلبات المساعدة القانونية المتبادلة وغيرها من طلبات التعاون الدولي هي:","o":["وزارة العدل","وحدة مكافحة غسل الأموال وتمويل الإرهاب","وزارة الخارجية وشؤون المغتربين","النائب العام في عمان"],"a":0},{"q":"إذا تعلق طلب المساعدة القانونية المتبادلة بإجراءات غير قسرية، فإن:","o":["مبدأ ازدواجية التجريم لا يعمل به كشرط للمساعدة","مبدأ ازدواجية التجريم يعد شرطاً أساسياً للمساعدة","الطلب يرفض حكماً","الطلب يشترط موافقة مجلس الوزراء"],"a":0},{"q":"يشمل التعاون الدولي وفق المادة (38):","o":["طلبات تسليم المتهمين والمحكوم عليهم وطلبات تعقب الأموال أو تجميدها أو التحفظ عليها","تبادل المعلومات الضريبية فقط","تسليم المتهمين فقط دون الأموال","تنفيذ الأحكام المدنية الأجنبية"],"a":0}]},{"n":"39","chapter":"","source":"أ. للجهات القضائية المختصة ان تأمر بتنفيذ طلبات الجهات غير الاردنية المختصة بحجز ومصادرة المتحصلات محل جرائم غسل الأموال أو الجرائم الأصلية المرتبطة بها أو تمويل الإرهاب والوسائط المستخدمة أو المنوي استخدامها، وذلك وفق القوانين المعمول بها أو الاتفاقيات التي صادقت عليها المملكة شريطة ألا يتعارض ذلك مع التشريعات النافذة.\nب. يتم توزيع حصيلة الاموال المحكوم بمصادرتها نهائيا وفقا لأحكام هذا القانون بموجب الاتفاقات التي تعقد بين الدول ذات العلاقة.","notes":[],"title":"تنفيذ طلبات الحجز الأجنبية","memo":"⭐ للجهات القضائية المختصة الأمر بتنفيذ طلبات الجهات غير الأردنية بحجز ومصادرة المتحصلات والوسائط وفق القوانين أو الاتفاقيات بشرط عدم التعارض مع التشريعات النافذة\n⭐ توزع حصيلة الأموال المحكوم بمصادرتها نهائياً بموجب الاتفاقات بين الدول ذات العلاقة","qs":[{"q":"توزع حصيلة الأموال المحكوم بمصادرتها نهائياً وفقاً لأحكام القانون بموجب:","o":["الاتفاقات التي تعقد بين الدول ذات العلاقة","قرار من مجلس الوزراء","قرار من المحكمة المختصة","تعليمات تصدرها اللجنة الوطنية"],"a":0},{"q":"الجهة التي لها أن تأمر بتنفيذ طلبات الجهات غير الأردنية المختصة بحجز ومصادرة المتحصلات هي:","o":["الجهات القضائية المختصة","الوحدة","وزارة العدل","دائرة الجمارك"],"a":0}]},{"n":"40","chapter":"","source":"لا تحول الاحكام المتعلقة بالسرية بما في ذلك السرية المصرفية المنصوص عليها في أي قانون آخر دون تطبيق أي من احكام هذا القانون.","notes":[],"title":"السرية لا تعطل القانون","memo":"⭐ لا تحول أحكام السرية بما فيها السرية المصرفية المنصوص عليها في أي قانون آخر دون تطبيق أحكام هذا القانون","qs":[{"q":"حالة عملية: رفض بنك تزويد الوحدة بمعلومات عن حساب عميل بحجة السرية المصرفية المقررة في قانون البنوك. وفق قانون مكافحة غسل الأموال:","o":["لا تحول أحكام السرية بما فيها السرية المصرفية دون تطبيق أحكام هذا القانون","يحق للبنك الرفض لأن السرية المصرفية مطلقة","يحق للبنك الرفض إلا بقرار قضائي","يحق للبنك الرفض إلا بموافقة العميل"],"a":0}]},{"n":"41","chapter":"","source":"أ. لمجلس الوزراء بناء على تنسيب اللجنة تشكيل لجنة فنية أو أكثر لتنفيذ قرارات مجلس الأمن المتعلقة بالإرهاب وتمويل الإرهاب وانتشار أسلحة الدمار الشامل.\nب. تقدم اللجنة الفنية المشكلة وفقاً لأحكام الفقرة (أ) من هذه المادة اقتراحاتها بتسمية الأشخاص والجماعات والكيانات على قوائم جزاءات الأمم المتحدة بما ينسجم مع قرارات مجلس الأمن ذات العلاقة.\nج. يتعين على المؤسسات المالية والمهن والاعمال غير المالية وأي شخص آخر القيام دون تأخير او اعلام مسبق بتجميد الاموال و الموارد الاقتصادية التي تعود ملكيتها كلياً أو جزئياً للشخص او الجماعة او الكيان المدرج والموجودة في حيازة او المسيطر عليها بشكل مباشر او غير مباشر لأي مما يلي :-\n1. أي شخص او جماعة او كيان تم ادراجه من قبل اللجنة الفنية وفقاً لأحكام الفقرة (ب) من هذه المادة.\n2. أي شخص او جماعة أو كيان تمت تسميته وفقاً لقرارات مجلس الأمن المتعلقة بالإرهاب وتمويل الإرهاب وانتشار اسلحة الدمار الشامل.\nد. باستثناء الحالات المنصوص عليها في التعليمات الصادرة بمقتضى الفقرة (و) من هذه المادة، يحظر على أي شخص إتاحة الأموال أو الأصول أو الموارد الاقتصادية أو المالية أو تقديم الخدمات المالية أو غيرها من الخدمات بشكل كامل أو مشترك أو بطريقة مباشرة أو غير مباشرة أو لمنفعة أي من الأشخاص المشار إليهم في هذه المادة او الى الذين يعملون بالنيابة عنهم أو بتوجيه منهم.\nهـ. تنتفي المسؤولية الجزائية أو المدنية أو الإدارية عن أي شخص يقوم بتجميد الأموال والموارد الاقتصادية بما ينسجم مع احكام هذه المادة.\nو. تصدر اللجنة التعليمات التي تنظم إجراءات إدراج الأشخاص والجماعات والكيانات على قوائم الجزاءات أو اقتراح الادراج في هذه القوائم والاستثناءات من التجميد.\nز. يعاقب بالحبس مدة لا تزيد على ثلاث سنوات أو بغرامة لا تقل عن مائة ألف دينار أو بكلتا هاتين العقوبتين كل من يخالف أحكام الفقرتين (ج) و(د) من هذه المادة.","notes":[],"title":"العقوبات المالية المستهدفة","memo":"⭐ لمجلس الوزراء بتنسيب اللجنة تشكيل لجنة فنية أو أكثر لتنفيذ قرارات مجلس الأمن\n⭐ التجميد دون تأخير أو إعلام مسبق لأموال المدرجين، وحظر إتاحة الأموال أو الخدمات لهم\n⭐ تنتفي المسؤولية عمن يجمد بما ينسجم مع المادة؛ واللجنة تصدر تعليمات الإدراج والاستثناءات\n⭐ عقوبة مخالفة الفقرتين (ج) و(د): حبس لا يزيد على 3 سنوات أو غرامة لا تقل عن 100,000 دينار أو كلتاهما","qs":[{"q":"تشكل اللجنة الفنية لتنفيذ قرارات مجلس الأمن المتعلقة بالإرهاب وتمويله وانتشار أسلحة الدمار الشامل بقرار من:","o":["مجلس الوزراء بناء على تنسيب اللجنة","اللجنة الوطنية بناء على تنسيب رئيس الوحدة","المحافظ","وزير الخارجية وشؤون المغتربين"],"a":0},{"q":"يتعين على المؤسسات المالية تجميد أموال الأشخاص والكيانات المدرجة على قوائم الجزاءات:","o":["دون تأخير أو إعلام مسبق","خلال خمسة أيام عمل من الإدراج بعد إعلام صاحب المال","بعد صدور قرار من المدعي العام","بعد موافقة الوحدة الخطية"],"a":0},{"q":"يعاقب من يخالف واجب التجميد أو حظر إتاحة الأموال للمدرجين وفق المادة (41) بالحبس مدة لا تزيد على ثلاث سنوات أو بغرامة:","o":["لا تقل عن مائة ألف دينار","لا تقل عن عشرة آلاف دينار ولا تزيد على مائتي ألف دينار","لا تتجاوز مائة ألف دينار","لا تقل عن ضعف قيمة الأموال غير المجمدة"],"a":0},{"q":"تصدر التعليمات التي تنظم إجراءات الإدراج على قوائم الجزاءات والاستثناءات من التجميد من قبل:","o":["اللجنة الوطنية","اللجنة الفنية","مجلس الوزراء","الوحدة"],"a":0}]},{"n":"42","chapter":"","source":"تعتبر الوحدة الخلف القانوني والواقعي لوحدة مكافحة غسل الاموال وتمويل الارهاب المنشأة بمقتضى أحكام قانون مكافحة غسل الاموال وتمويل الارهاب رقم (46) لسنة 2007 وتحل محلها في كل ما لها من حقوق وما عليها من التزامات.","notes":[],"title":"الخلف القانوني للوحدة السابقة","memo":"⭐ الوحدة الخلف القانوني والواقعي للوحدة المنشأة بموجب القانون رقم (46) لسنة 2007\n⭐ تحل محلها في جميع حقوقها والتزاماتها","qs":[{"q":"تعتبر وحدة مكافحة غسل الأموال وتمويل الإرهاب الحالية الخلف القانوني والواقعي للوحدة المنشأة بمقتضى:","o":["قانون مكافحة غسل الأموال وتمويل الإرهاب رقم (46) لسنة 2007","قانون البنك المركزي الأردني","قانون منع الإرهاب","قانون مكافحة غسل الأموال وتمويل الإرهاب رقم (20) لسنة 2015"],"a":0},{"q":"تحل الوحدة الحالية محل الوحدة المنشأة بموجب القانون السابق في:","o":["كل ما لها من حقوق وما عليها من التزامات","حقوقها فقط دون التزاماتها","التزاماتها المالية فقط","موظفيها فقط دون أموالها"],"a":0}]},{"n":"43","chapter":"","source":"يصدر مجلس الوزراء الانظمة اللازمة لتنفيذ أحكام هذا القانون .","notes":[],"title":"الأنظمة التنفيذية","memo":"⭐ يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ أحكام القانون","qs":[{"q":"الجهة التي تصدر الأنظمة اللازمة لتنفيذ أحكام قانون مكافحة غسل الأموال وتمويل الإرهاب هي:","o":["مجلس الوزراء","اللجنة الوطنية","المحافظ","الوحدة"],"a":0}]},{"n":"44","chapter":"","source":"يلغى ( قانون مكافحة غسل الأموال وتمويل الارهاب رقم (46) لسنة 2007 ) على أن يستمر العمل بالأنظمة والتعليمات والقرارات الصادرة بمقتضاه إلى أن تعدل أو تلغى أو يستبدل غيرها بها وفقاً لأحكامه.","notes":[],"title":"إلغاء القانون السابق","memo":"⭐ يلغى قانون مكافحة غسل الأموال وتمويل الإرهاب رقم (46) لسنة 2007\n⭐ يستمر العمل بالأنظمة والتعليمات والقرارات الصادرة بمقتضاه إلى أن تعدل أو تلغى أو يستبدل غيرها بها","qs":[{"q":"بعد إلغاء قانون مكافحة غسل الأموال وتمويل الإرهاب رقم (46) لسنة 2007، فإن الأنظمة والتعليمات والقرارات الصادرة بمقتضاه:","o":["يستمر العمل بها إلى أن تعدل أو تلغى أو يستبدل غيرها بها","تلغى حكماً من تاريخ نفاذ القانون الجديد","يستمر العمل بها لمدة سنة واحدة فقط","يستمر العمل بها بعد موافقة اللجنة الوطنية عليها"],"a":0},{"q":"القانون الذي ألغاه قانون مكافحة غسل الأموال وتمويل الإرهاب لسنة 2021 هو:","o":["قانون مكافحة غسل الأموال وتمويل الإرهاب رقم (46) لسنة 2007","قانون منع الإرهاب لسنة 2006","قانون البنك المركزي الأردني لسنة 1971","قانون مكافحة الفساد لسنة 2016"],"a":0}]},{"n":"45","chapter":"","source":"رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون.","notes":[],"title":"تنفيذ القانون","memo":"⭐ رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام القانون","qs":[]}]};
